	private String assignRoleswithProxy(String userName) {
		Session session = this.sessionFactory.getCurrentSession();
		String userId = null;
		try {
			// checking the particular user in the proxy table.
			Criteria crit = session.createCriteria(ProxyAccess.class,"Proxy").add(Restrictions.eq("userADId",userName)).add(Restrictions.eq("isActive", 1));
			List<ProxyAccess> accessList = crit.list();
			AppLoger.APPLOGGER.info("Query Count: " + 4);
			if(accessList.size()>0) {
				// get the user id from the table to check from local table and check the data in access control table 
				userId = accessList.get(0).getProxyADId();
				String currentLoggedUser = org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication().getName();
				currentLoggedUser = userId;
			}
		}catch (Exception e) {
		} finally {
			//session.close();
		}
		
		return userId;
	}

