	@Override
	public ResponseEntity<Object> updateCountryDetails(Country[] countryDetails) {
		AppLoger.APPLOGGER.info("inside impl");
		AppLoger.APPLOGGER.info("Query Count function: " + 11);
		Session session = this.sessionFactory.getCurrentSession();
		session.beginTransaction();
		int insertId = 0;
		try{		
			for (Country countryDetail : countryDetails) 
			{
				Query qryCountryUpdate = session.createQuery("UPDATE Country set countryName=:countryName, currencyCode = :currencyCode, "
						+ "exchangeRate = :exchangeRate, syntelFacilityCost=:syntelFacilityCost, isOnlyManRCDeal=:isOnlyManRCDeal, isActive=:isActive where countryId = :countryId");
				qryCountryUpdate.setParameter("countryName", countryDetail.getCountryName());
				qryCountryUpdate.setParameter("currencyCode", countryDetail.getCurrencyCode());
				qryCountryUpdate.setParameter("exchangeRate", countryDetail.getExchangeRate());
				qryCountryUpdate.setParameter("syntelFacilityCost", countryDetail.getSyntelFacilityCost());
				qryCountryUpdate.setParameter("countryId", countryDetail.getCountryId());
				qryCountryUpdate.setParameter("isOnlyManRCDeal", countryDetail.getIsOnlyManRCDeal());
				qryCountryUpdate.setParameter("isActive", countryDetail.getIsActive());
				
				insertId = qryCountryUpdate.executeUpdate();
				
				Query qryCityUpdate = session.createQuery("UPDATE City set syntelPremium=:syntelPremium where countryId = :countryId");
				qryCityUpdate.setParameter("syntelPremium", countryDetail.getSyntelFacilityCost());
				qryCityUpdate.setParameter("countryId", countryDetail.getCountryId());
				
				insertId = qryCityUpdate.executeUpdate();
			}	
			
			AppLoger.APPLOGGER.info("updated");
			
			Query salaryUpdateProc = session.createSQLQuery("{CALL synprod.RP_Deal_Salary_Designation_Calculation}");
			AppLoger.APPLOGGER.info("RP_Deal_Salary_Designation_Calculation==="+salaryUpdateProc);
			List salaryUpdateList = salaryUpdateProc.list();
			AppLoger.APPLOGGER.info("RESULT1");
			AppLoger.APPLOGGER.info(salaryUpdateList.size());
			
			session.getTransaction().commit();
			
			return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body("Data Inserted Successfully");
		}
		catch (Exception e) 
		{
			session.getTransaction().rollback();
			throw e;
		} finally {
			//session.close();
		}
	}

