	@Override
	public ResponseEntity<Object> getRateCardName(int customerId, String deal_Id,int cityId, int countryId,int Industry_ID) {
		Session session = this.sessionFactory.getCurrentSession();
		int categoryId = 0;
		String currencyId = null;
		Integer rateCardId=null;
		List <RateCardDetails> rateCardMappingList=new ArrayList<RateCardDetails>();
		List <RateCardDetails>ratecardNamelist=new ArrayList<RateCardDetails>();
		List <RateCardDetails>rateCarList=new ArrayList<RateCardDetails>();
		
		try {
			
			Criteria cityCategory = session.createCriteria(City.class).add(Restrictions.eq("cityId", cityId));
			List<City> cityCateg = cityCategory.list();
			if(cityCateg.size()!=0) {
				categoryId = cityCateg.get(0).getCategorizationId();
			}
			
			Criteria countryCurrency = session.createCriteria(Country.class).add(Restrictions.eq("countryId", countryId));
			List<Country> currencyIdList = countryCurrency.list();
			if(currencyIdList.size()!=0) {
				currencyId = currencyIdList.get(0).getCurrencyId();
			}
			
			Criteria cr2 = session.createCriteria(Deal.class).add(Restrictions.eq("crmDealId", deal_Id));
			List<Deal> dealDetail = cr2.list();
			
			
			Criteria rcMultiCust = session.createCriteria(MultipleRcCustomerMapping.class).add(Restrictions.eq("customerId", customerId));
			List<MultipleRcCustomerMapping> rcMultiCustLst = rcMultiCust.list();
			if(rcMultiCustLst.size()!=0) {
				for(int i=0;i<rcMultiCustLst.size();i++){
				
					
					String qryForRateCardName = "select * "
							+ "from [synprod].[RP_Rate_Card_Details] a, [synprod].[RP_Rate_Card_Location] B, [synprod].[MST_RP_City] c,"
							+ "[synprod].[RP_Rate_Card_Currency_Utilization] D where  a.RC_Id= "+rcMultiCustLst.get(i).getRcId()+" and a.RC_Id = b.RC_Id and a.rc_id = d.rc_ID and b.RC_Id = d.RC_Id "
							+ "and b.city_id = c.city_ID and  c.Categorization_Id ="+categoryId+" and a.Is_IT_KPO= "+Industry_ID+" and "
							+ "b.Country_Id = d.base_country_id "
							+ " and  B.COUNTRY_id = "+countryId+"  "
							+ "and RC_Start_Date <= (select deal_start_date from  [synprod].[RP_Deal_CRM_Stage] where crm_deal_id= '"+deal_Id+"')"
							+ " and Expected_RC_End_Date  >= (select deal_start_date from  [synprod].[RP_Deal_CRM_Stage] where crm_deal_id = '"+deal_Id+"')"
							+ "  and Current_Approval_Status = 3";
					Query crit = session.createSQLQuery(qryForRateCardName).addEntity(RateCardDetails.class);
					rateCardMappingList=crit.list();
					if(!rateCardMappingList.isEmpty()){
						ratecardNamelist.add(rateCardMappingList.get(0));
					}
					
					
				}
				
			}
			
			
			
			String qryForRateCardName = "select * "
					+ "from [synprod].[RP_Rate_Card_Details] a, [synprod].[RP_Rate_Card_Location] B, [synprod].[MST_RP_City] c,"
					+ "[synprod].[RP_Rate_Card_Currency_Utilization] D where a.RC_Id = b.RC_Id and a.rc_id = d.rc_ID and b.RC_Id = d.RC_Id "
					+ "and b.city_id = c.city_ID and  c.Categorization_Id ="+categoryId+" and a.Is_IT_KPO= "+Industry_ID+" and "
					+ "b.Country_Id = d.base_country_id "
					+ " and  B.COUNTRY_id = "+countryId+"  "
					+ "and RC_Start_Date <= (select deal_start_date from  [synprod].[RP_Deal_CRM_Stage] where crm_deal_id= '"+deal_Id+"')"
					+ " and Expected_RC_End_Date  >= (select deal_start_date from  [synprod].[RP_Deal_CRM_Stage] where crm_deal_id = '"+deal_Id+"')"
					+ " and CUSTOMER_id = "+customerId+"  and Current_Approval_Status = 3";
			System.out.println("qryForRateCardName================="+qryForRateCardName);
			Query crit = session.createSQLQuery(qryForRateCardName).addEntity(RateCardDetails.class);		
			
			rateCarList = crit.list();
			if(!rateCarList.isEmpty()){
				ratecardNamelist.addAll(rateCarList);
			}
			
			
			AppLoger.APPLOGGER.info("==getRateCardName==size=" + ratecardNamelist.size() + " qry=" + crit);
			AppLoger.APPLOGGER.info("Query Count function: " + 18);
			if (!ratecardNamelist.isEmpty()) {
				return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(ratecardNamelist);
			} else {
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body(ratecardNamelist);
				// //session.close();
			}
		} catch (Exception e) {
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently Facing Techinal issue"+e.getMessage());
		} finally {
			//session.close();
		}
	}

