	private boolean isCityExists(ViewCitiesData cityDetailsAdd) {
		Session session = this.sessionFactory.getCurrentSession();
		try {
			Query query = session.createQuery("from ViewCitiesData where cityName = :cityName and countryId= :countryId and isActive = 1");
			query.setParameter("cityName", cityDetailsAdd.getCityName());
			query.setParameter("countryId", cityDetailsAdd.getCountryId());
			List list = query.list();
			AppLoger.APPLOGGER.info("Size:" + list.size());
			AppLoger.APPLOGGER.info("Query Count function: " + 24);
			return (list.size() >= 1) ? true : false;
		} catch (Exception e) {
			return false;
		} finally {
			//session.close();
		}
	}

