	@Override
	public ResponseEntity<Object> uploadEstimationDealFile(MultipartFile file, String fileName, InputStream uploadedInputStream,
			FileObjectTable fileObj, Integer versionId, FPDealAttachment fpData,EstimationAttachment eAData) {
		int manualUploadId = 0;
		Session session = this.sessionFactory.getCurrentSession();
		AppLoger.APPLOGGER.info("@Repository*+-*+-*+*+*+*+*+*+-*");
		AppLoger.APPLOGGER.info("Query Count function File Upload function");
		try {
			// File Writing to D Disk
			byte[] byteArrayString = file.getBytes();
			ByteArrayInputStream ba = new ByteArrayInputStream(byteArrayString);
			System.out.println("converting to byteInpurtStream");
			File files = new File("D:\\FTP\\Rightprice\\Ratecard\\");
			System.out.println("snapbill present is " + files.exists());
			if (!files.exists()) {
				if (files.mkdirs()) {
					System.out.println("Snapbill directories are created!");
				} else {
					System.out.println("Already Present!");
				}
			}
			FileOutputStream outputStream = null;
			String filName = "";
			try {
				System.out.println("The Original File name is......... ");
				System.out.println(fileObj.getOriginalFileName());
				File file1 = new File("D:\\FTP\\Rightprice\\Ratecard\\" + fileObj.getOriginalFileName() + ".xlsx");
				int increase = 0;
				filName = fileObj.getOriginalFileName();
				while (file1.exists()) {
					String strMain = fileObj.getOriginalFileName();
					String[] arrSplit = new String[2];
					arrSplit = strMain.split("\\.");
					increase++;
					file1 = new File("D:\\FTP\\Rightprice\\Ratecard\\" + arrSplit[0] + "(" + increase + ")" + ".xlsx");
					filName = arrSplit[0] + "(" + increase + ")"+"_"+auditTrails.getCurrentTimeStamp();
				}
				outputStream = new FileOutputStream(file1);
			} catch (FileNotFoundException e1) {
				e1.printStackTrace();
			}

			int read = 0;
			byte[] bytes = new byte[1024];
			try {
				while ((read = ba.read(bytes)) != -1) {

					outputStream.write(bytes, 0, read);
				}
				outputStream.close();
			} catch (IOException e1) {
				// TODO Auto-generated catch block
				e1.printStackTrace();
			}
			// File Writing has ended
			fileObj.setFileName(filName);
			int insertId = (int) session.save(fileObj);
			AppLoger.APPLOGGER.info("file insertId : " + insertId);

			AppLoger.APPLOGGER.info("@adding data to RP_Attachments *+-*+-*+*+*+*+*+*+-*");

			fpData.setAttachmentId(insertId);
			eAData.setAttachmentId(insertId);
			session.save(fpData);
			session.save(eAData);
			AppLoger.APPLOGGER.info("file insertId : " + insertId);
			return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body("File Inserted SuccesFully");
		
		} catch (Exception e) {
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN)
					.body("Currently Facing Technical Issue."+e.getMessage());
		} finally {
			//session.close();
		}
	}

	
