	@Override
	public ResponseEntity<Object> updateDesignation(Designation designation) {
		int updateDesignation = 0;
		Session session = this.sessionFactory.getCurrentSession();
		AppLoger.APPLOGGER.info("Query Count function: " + 50);
		try {
			
			Query query = session.createQuery(
					"UPDATE Designation set empBandId=:empBandId,empGradeId=:empGradeId,minimumExperienceYears=:minimumExperienceYears,maximumExperienceYears=:maximumExperienceYears,isActive = :isActive,updatedBy=:updatedBy,updatedOn=:updatedOn where empDesignationId= :empDesignationId");
			query.setParameter("empBandId", designation.getEmpBandId());
			query.setParameter("empGradeId", designation.getEmpGradeId());
			query.setParameter("minimumExperienceYears", designation.getMinimumExperienceYears());
			query.setParameter("maximumExperienceYears", designation.getMaximumExperienceYears());
			query.setParameter("isActive", designation.getIsActive());
			query.setParameter("updatedBy", designation.getUpdatedBy());
			query.setParameter("updatedOn", designation.getUpdatedOn());
			query.setParameter("empDesignationId", designation.getEmpDesignationId());
			updateDesignation = query.executeUpdate();
			if (updateDesignation > 0) {
				return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(updateDesignation);
			} else {
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently We are facing technical issues, please try again later.");
			}
		}catch (Exception e) {
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently We are facing technical issues, please try again later."+e.getMessage());
		} finally {
			//session.close();
		}
	} 

