	@Override
	public ResponseEntity<Object> addVertical(Vertical vertical) {
		int insertId = 0;
			AppLoger.APPLOGGER.info("Query Count function: " + 56);
			boolean check = this.checkVertical(vertical);
			AppLoger.APPLOGGER.info("Checking LOB_CODE:" + check);
			if (!check) {
				return ResponseEntity.status(203).contentType(MediaType.TEXT_PLAIN).body("Vertical already exist. Please Update the vertical");
			}
			Session session = this.sessionFactory.getCurrentSession();
			try {
				session.beginTransaction();
				session.save(vertical);
				insertId = vertical.getVerticalId();
				session.getTransaction().commit();
				return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(insertId);
			} catch (Exception e) {
				session.getTransaction().rollback();
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN)
						.body("Currently We are facing technical issues, please try again later.");
			} finally {
				//session.close();
			}
			
	}

	@Override
	public ResponseEntity<Object> updateVertical(Vertical vertical) {
		int updateVertical = 0;
		Session session = this.sessionFactory.getCurrentSession();
		try 
		{
			AppLoger.APPLOGGER.info("Query Count function: " + 57);
			Query query = session.createQuery("UPDATE Vertical set deliveryHeadId=:deliveryHeadId,buHeadId=:buHeadId,"
					+ "DUH=:DUH,BUH=:BUH,deliveryHeadEmail=:deliveryHeadEmail,"
					+ "buHeadEmail=:buHeadEmail,isActive=:isActive,"
					+ "verticalStatusFlag=:verticalStatusFlag,updatedBy=:updatedBy,updatedOn=:updatedOn "
					+ "where verticalName = :verticalName");
			
			query.setParameter("deliveryHeadId", vertical.getDeliveryHeadId());
			query.setParameter("buHeadId", vertical.getBuHeadId());
			//query.setParameter("RiskManagersPersonId", vertical.getRiskManagersPersonId());
			query.setParameter("DUH", vertical.getDUH());
			query.setParameter("BUH", vertical.getBUH());
			//query.setParameter("RiskManagers", vertical.getRiskManagers());
			query.setParameter("deliveryHeadEmail", vertical.getDeliveryHeadEmail());
			query.setParameter("buHeadEmail", vertical.getBuHeadEmail());
			//query.setParameter("RiskManagersPersonEmail", vertical.getRiskManagersPersonEmail());
			query.setParameter("isActive", vertical.getIsActive());
			query.setParameter("verticalStatusFlag", vertical.getVerticalStatusFlag());
			query.setParameter("updatedBy", vertical.getUpdatedBy());
			query.setParameter("updatedOn", vertical.getUpdatedOn());
			query.setParameter("verticalName", vertical.getVerticalName());
			
			updateVertical = query.executeUpdate();
			if (updateVertical > 0) {
				return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(updateVertical);
			} else {
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently We are facing technical issues, please try again later.");
			}
		} catch (Exception e) {
			//session.getTransaction().rollback();
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN)
					.body("Currently We are facing technical issues, please try again later.");
		} finally {
			//session.close();
		}
	}

