	private boolean isMasterRoleExists(MasterRoles masterRoles) {
		Session session = this.sessionFactory.getCurrentSession();
		try {
			AppLoger.APPLOGGER.info("Query Count function: " + 70);
			Query query = session.createQuery("from MasterRoles where (masterRoleName = :masterRoleName or masterRoleLongDescription= :masterRoleLongDescription) and isActive = 1");
			query.setParameter("masterRoleName", masterRoles.getMasterRoleName());
			query.setParameter("masterRoleLongDescription", masterRoles.getMasterRoleLongDescription());
			List list = query.list();
			AppLoger.APPLOGGER.info("Size:" + list.size());
			return (list.size() >= 1) ? true : false;
		} catch (Exception e) {
			return false;
		} finally {
			//session.close();
		}

	}
	@Override
	public ResponseEntity<Object> updateRole(MasterRoles masterRoles) {
		int updateMasterRoles = 0;
		Session session = this.sessionFactory.getCurrentSession();
		try {
			AppLoger.APPLOGGER.info("Query Count function: " + 71);
			Query query = session.createQuery(
					"UPDATE MasterRoles set masterRoleShortDescription=:masterRoleShortDescription,masterRoleLongDescription=:masterRoleLongDescription,"
							+ "subPracticeId=:subPracticeId,proficiencyLevelId=:proficiencyLevelId,proficiencyLevelDescription=:proficiencyLevelDescription,"
							+ "skillsId=:skillsId,skillDescription=:skillDescription,x0SkillId=:x0SkillId,x0SkillDescription=:x0SkillDescription,x0SkillElementId=:x0SkillElementId,"
							+ "x0SkillElementDescription=:x0SkillElementDescription,x0KnowledgeAreaId=:x0KnowledgeAreaId,x0KnowledgeAreaDescription=:x0KnowledgeAreaDescription,"
							+ "x0ProficiencyId=:x0ProficiencyId,x0ProficiencyDescription=:x0ProficiencyDescription,designationId=:designationId,designationId2=:designationId2,designationId3=:designationId3,"
							+ "designationId4=:designationId4,designation1Percent=:designation1Percent,designation2Percent=:designation2Percent,designation3Percent=:designation3Percent,designation4Percent=:designation4Percent,"
							+ "syntelRoleId=:syntelRoleId,syntelRoleDescription=:syntelRoleDescription,isActive=:isActive,updatedBy=:updatedBy,updatedDate=:updatedDate "
							+ "where masterRoleName=:masterRoleName");
			query.setParameter("masterRoleShortDescription", masterRoles.getMasterRoleShortDescription());
			query.setParameter("masterRoleLongDescription", masterRoles.getMasterRoleLongDescription());
			query.setParameter("subPracticeId", masterRoles.getSubPracticeId());
			query.setParameter("proficiencyLevelId", masterRoles.getProficiencyLevelId());
			query.setParameter("proficiencyLevelDescription", masterRoles.getProficiencyLevelDescription());
			query.setParameter("skillsId", masterRoles.getSkillsId());
			query.setParameter("skillDescription", masterRoles.getSkillDescription());
			query.setParameter("x0SkillId", masterRoles.getX0SkillId());
			query.setParameter("x0SkillDescription", masterRoles.getX0SkillDescription());
			query.setParameter("x0SkillElementId", masterRoles.getX0SkillElementId());
			query.setParameter("x0SkillElementDescription", masterRoles.getX0SkillElementDescription());
			query.setParameter("x0KnowledgeAreaId", masterRoles.getX0KnowledgeAreaId());
			query.setParameter("x0KnowledgeAreaDescription", masterRoles.getX0KnowledgeAreaDescription());
			query.setParameter("x0ProficiencyId", masterRoles.getX0ProficiencyId());
			query.setParameter("x0ProficiencyDescription", masterRoles.getX0ProficiencyDescription());
			query.setParameter("designationId", masterRoles.getDesignationId());
			query.setParameter("designationId2", masterRoles.getDesignationId2());
			query.setParameter("designationId3", masterRoles.getDesignationId3());
			query.setParameter("designationId4", masterRoles.getDesignationId4());
			query.setParameter("designation1Percent", masterRoles.getDesignation1Percent());
			query.setParameter("designation2Percent", masterRoles.getDesignation2Percent());
			query.setParameter("designation3Percent", masterRoles.getDesignation3Percent());
			query.setParameter("designation4Percent", masterRoles.getDesignation4Percent());
			query.setParameter("syntelRoleId", masterRoles.getSyntelRoleId());
			query.setParameter("syntelRoleDescription", masterRoles.getSyntelRoleDescription());
			query.setParameter("isActive", masterRoles.getIsActive());
			query.setParameter("updatedBy", masterRoles.getUpdatedBy());
			query.setParameter("updatedDate", masterRoles.getUpdatedDate());
			query.setParameter("masterRoleName", masterRoles.getMasterRoleName());
			updateMasterRoles = query.executeUpdate();
			if (updateMasterRoles > 0) {
				return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(updateMasterRoles);
			} else {
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently We are facing technical issues, please try again later.");
			}
		} catch (Exception e) {
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently We are facing technical issues, please try again later.");
		} finally {
			//session.close();
		}
	}

