	@Override
	public ResponseEntity<Object> insertDealData(Deal dealData) {		
		Session session = this.sessionFactory.getCurrentSession();
		int oldDealVersionId = 0;
		int insertId = 0;
		AppLoger.APPLOGGER.info("Query Count function: " + 80);
		try{
			session.beginTransaction();
			oldDealVersionId = dealData.getRpDealVersionId();
			session.save(dealData);
			insertId = dealData.getRpDealVersionId();
			session.getTransaction().commit();
			
			int storeProcResultProc = 0;
			Criteria crit = session.createCriteria(Deal.class,"DealData").add(Restrictions.eq("rpDealVersionId", insertId));
			//List<FpDeal> deal = crit.list();
			List<Deal> deal = crit.list();
			if(crit.list().size() > 0 ) {
				String dealId = deal.get(0).getCrmDealId();
				AppLoger.APPLOGGER.info("Deal ID is........... "+ dealId);
				Query storeProcQuery = session.createSQLQuery("{CALL synprod.RP_update_Deal_Month_Diff(:crmDealId)}")
						.setParameter("crmDealId", dealId);
				List result = storeProcQuery.list();
				AppLoger.APPLOGGER.info("RESULT");
				AppLoger.APPLOGGER.info(result);
				storeProcResultProc = result.indexOf("SUCCESS");
				
				if(oldDealVersionId > 0) {
					Query newVersionProcQuery = session.createSQLQuery("{CALL synprod.RP_TM_Deal_New_Version_Copy(:oldversionID,:versionId)}")
							.setParameter("oldversionID", oldDealVersionId).setParameter("versionId", insertId);
					List newVersionProc = newVersionProcQuery.list();
					AppLoger.APPLOGGER.info("RESULT");
					AppLoger.APPLOGGER.info(newVersionProc);
					storeProcResultProc = newVersionProc.indexOf("SUCCESS");
				}
			}
		}
		
		catch (Exception e) {
			AppLoger.APPLOGGER.info("Exc----------------> " + e);
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN)
					.body("Currently We are facing technical issues, please try again later.");
		}
		//session.close();
		return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(insertId);
		
	}

