	private void UpdateRevisedRates(XSSFSheet sheet, RateCardDetails rateCardApprovalDetails, Session session, int countryId, int intCityId) throws Exception  
	{
		String syntelLanId= getSyntelId(this.auditTrails.getCurrentUser());
		// To do
		/*1. Read roles data save RP_Insert_Rate_Card_Roles_STG
		2. Save data in Rp_SaveRateCardRoles
		3.{CALL [synprod].[RP_Calculate_Role_Wise_Yearly_GM_Revenue_Cost_For_Rate_Card_Manual](:RC_Id,:Country_Id,:City_Id,:strCreatedBy)
		4. Call RP_UpdateRevisedRate	*/
		
		try
		{
			for (int j = 3; j <= sheet.getLastRowNum(); j++) 
			{
				sheet.getRow(j).getCell(1).setCellType(CellType.STRING);
				sheet.getRow(j).getCell(9).setCellType(CellType.STRING);
				
				if(sheet.getRow(j).getCell(1).getRichStringCellValue().toString().isEmpty()
						|| sheet.getRow(j).getCell(1).getRichStringCellValue().toString().equals("0"))
					break;
				
				double dblRevOnsiteRate = 0.0;
				double dblRevOffshoreRate = 0.0;
				
				try
				{
					dblRevOnsiteRate = sheet.getRow(j).getCell(38).getNumericCellValue();
				}
				catch(Exception Ex)
				{
					dblRevOnsiteRate = 0.0;
				}
				
				try
				{
					dblRevOffshoreRate = sheet.getRow(j).getCell(39).getNumericCellValue();
				}
				catch(Exception Ex)
				{
					dblRevOffshoreRate = 0.0;
				}
				
				// 4. Call RP_UpdateRevisedRate
				AppLoger.APPLOGGER.info("Inside RightPriceRepositoryImplementaion ==> uploadManualRateCard ==> saveFinalTandMData "
						+ "==> Calling stored procedure [synprod].[RP_UpdateRevisedRates]");
				ProcedureCall query = session.createStoredProcedureCall("[synprod].[RP_UpdateRevisedRates]");
				query.registerParameter("City_Id", Integer.class, ParameterMode.IN) .bindValue(intCityId);
				query.registerParameter("RC_Id", Integer.class, ParameterMode.IN).bindValue(rateCardApprovalDetails.getRcId());
				query.registerParameter("strRoleCode", String.class, ParameterMode.IN).bindValue(sheet.getRow(j).getCell(1).getRichStringCellValue().toString());
				query.registerParameter("strClientRole", String.class, ParameterMode.IN).bindValue(sheet.getRow(j).getCell(9).getRichStringCellValue().toString());
				query.registerParameter("dblRevOnsiteRate", Double.class, ParameterMode.IN).bindValue(dblRevOnsiteRate);
				query.registerParameter("dblRevOffshoreRate", Double.class, ParameterMode.IN).bindValue(dblRevOffshoreRate);
				if(syntelLanId.isEmpty() || syntelLanId==null)
				{
					query.registerParameter("strCreatedBy", String.class, ParameterMode.IN).bindValue(this.auditTrails.getCurrentUser());
					query.registerParameter("strUpdatedBy", String.class, ParameterMode.IN).bindValue(this.auditTrails.getCurrentUser());					
				}
				else
				{
					query.registerParameter("strCreatedBy", String.class, ParameterMode.IN).bindValue(syntelLanId);
					query.registerParameter("strUpdatedBy", String.class, ParameterMode.IN).bindValue(syntelLanId);					
				}
				
				ProcedureOutputs procedureResult = query.getOutputs();
				AppLoger.APPLOGGER.info("Executed  Stored Procedure [synprod].[RP_UpdateRevisedRates]  successfully");
			}
			
		}
		catch(Exception ex)
		{
			ex.printStackTrace();
			AppLoger.APPLOGGER.info("Error Occured in saveFinalTandMData: StackTrace :" + ex.getStackTrace());
			AppLoger.APPLOGGER.info("Error Occured in saveFinalTandMData: Error" + ex.getMessage());
			throw new Exception("Error Occured in saveFinalTandMData: " + ex.getMessage()); 
		}
	}
	
	private void processExcelData(InputStream stream, RateCardDetails rateCardApprovalDetails,Session session, int intCityId, int countryId) throws Exception 
	{
		try
		{
			
			// 3. read object
			/*ByteArrayInputStream objIS = new ByteArrayInputStream(fileData.get(0).getData());
			Create workbook object from byte input stream
			XSSFWorkbook workbook = new XSSFWorkbook(objIS);*/
			
			//Create workbook object from byte input stream
			XSSFWorkbook workbook = new XSSFWorkbook(stream);
			
			for(int i=0; i<workbook.getNumberOfSheets(); i++)
			{
				XSSFSheet sheet = workbook.getSheetAt(i);
				System.out.println("sheet Name: \t" + sheet.getSheetName());			
				
				if(sheet.getSheetName().equals("Final T&M"))
				{					
					//1. Read roles data save RP_Insert_Rate_Card_Roles_STG
					ArrayList<RateCardRolesSTG> arrLiRcRolesSTG = new ArrayList<RateCardRolesSTG>();
					for (int j = 3; j <= sheet.getLastRowNum(); j++) 
					{
						RateCardRolesSTG objRCRoleStg =  new RateCardRolesSTG();
						
						sheet.getRow(j).getCell(1).setCellType(CellType.STRING);
						sheet.getRow(j).getCell(9).setCellType(CellType.STRING);
						
						if(sheet.getRow(j).getCell(1).getRichStringCellValue().toString().isEmpty() 
								|| sheet.getRow(j).getCell(1).getRichStringCellValue().toString().equals("0"))
							break;
						
						double dblRevOnsiteRate = 0.0;
						double dblRevOffshoreRate = 0.0;
						
						try
						{
							dblRevOnsiteRate = sheet.getRow(j).getCell(38).getNumericCellValue();
						}
						catch(Exception Ex)
						{
							dblRevOnsiteRate = 0.0;
						}
						
						try
						{
							dblRevOffshoreRate = sheet.getRow(j).getCell(39).getNumericCellValue();
						}
						catch(Exception Ex)
						{
							dblRevOffshoreRate = 0.0;
						}
						
						// 6. Insert this data in temporary table
						objRCRoleStg.setRcId(rateCardApprovalDetails.getRcId());
						objRCRoleStg.setRole(sheet.getRow(j).getCell(1).getRichStringCellValue().toString());
						objRCRoleStg.setClientRole(sheet.getRow(j).getCell(9).getRichStringCellValue().toString());
						objRCRoleStg.setOnsiteCustomerRate(dblRevOnsiteRate);
						objRCRoleStg.setOffshoreCustomerRate(dblRevOffshoreRate);
						objRCRoleStg.setCountryId(countryId);
						objRCRoleStg.setCityId(intCityId);
						String syntelLanId= getSyntelId(this.auditTrails.getCurrentUser());
						if(syntelLanId.isEmpty() || syntelLanId==null)
						{
							objRCRoleStg.setCreatedBy(this.auditTrails.getCurrentUser());
							objRCRoleStg.setUpdatedBy(this.auditTrails.getCurrentUser());
						}
						else
						{
							objRCRoleStg.setCreatedBy(syntelLanId);
							objRCRoleStg.setUpdatedBy(syntelLanId);
						}
						
						arrLiRcRolesSTG.add(objRCRoleStg);
					}
					//  save RP_Insert_Rate_Card_Roles_STG
					//  Save data in Rp_SaveRateCardRoles
					// {CALL [synprod].[RP_Calculate_Role_Wise_Yearly_GM_Revenue_Cost_For_Rate_Card_Manual](:RC_Id,:Country_Id,:City_Id,:strCreatedBy)
					uploadMannualRCData(arrLiRcRolesSTG,session,countryId,intCityId,rateCardApprovalDetails.getRcId());
					
					//UpdateRevisedRates(sheet,rateCardApprovalDetails,session,countryId,intCityId);
				}
			}
			workbook.close();
			stream.close();
		}
		catch(Exception ex)
		{
			ex.printStackTrace();
			AppLoger.APPLOGGER.info("Error Occured in processExcelData: StackTrace :" + ex.getStackTrace());
			AppLoger.APPLOGGER.info("Error Occured in processExcelData: Error" + ex.getMessage());
			throw new Exception("Error Occured in processExcelData: " + ex.getMessage()); 
		}
		
	}
	
