	    BigDecimal tcvValue=null;
	   // List<RiskManagersAdminMail> RiskManagersAdminMails=null;
	    AppLoger.APPLOGGER.info(lastComment[lastComment.length-1].trim());
	    String RejectedComments=lastComment[lastComment.length-1].trim();
	    
	    
	    Query querys = session.createQuery("from RcInfoMailTriger WHERE rcId=?");
