	private int getCurrentUserVerticalId() {
		String syntelID= getSyntelId(auditTrails.getCurrentUser());
		int verticalId = 0;
		int verticalGroupId = 0;
		String getVerticalId = "SELECT VERTICAL_ID, VERTICAL_GROUP_ID"
				+ "FROM [synprod].[MST_RP_EMP_INFORMATION_WITH_CONTRACT_EMPLOYEES]"
				+ "WHERE DAS_Id=? AND Is_Active=?";
		
		try {
			AppLoger.APPLOGGER.info("Query : " + getVerticalId);
			AppLoger.APPLOGGER.info("Query Count function: " + 100);
			SqlRowSet set = mssqlTemplate.queryForRowSet(getVerticalId,
					new Object[] { syntelID, 1 });
			AppLoger.APPLOGGER.info("Query Status: " + !set.wasNull());
			while (set.next()) {
				verticalId = set.getInt("VERTICAL_ID");
				verticalGroupId = set.getInt("VERTICAL_GROUP_ID");
				AppLoger.APPLOGGER.info(" verticalId : " + verticalId + " verticalGroupId : " + verticalGroupId);
			}
		} catch (Exception e) {
			e.printStackTrace();
		}
		return verticalGroupId;
	}

	public List<String> getDeliveryDirectorDetails() {
		String syntelID= getSyntelId(auditTrails.getCurrentUser());
		String deliveryDirectorName = null;
		List<String> deliveryDirectorDetails = new ArrayList();
		/* String deliveryDirectorID = null; */
		String getUserInfo = " SELECT FNAME +' '+ LNAME AS EMP_NAME,[PROJECT_ID], VERTICAL_ID,VERTICAL_GROUP_ID,  GRADE AS BAND_GRADE "
				+ "FROM [synprod].[MST_RP_EMP_INFORMATION_WITH_CONTRACT_EMPLOYEES]"
				+ " WHERE DAS_Id=? AND Is_Active=?";
		
		try {
			AppLoger.APPLOGGER.info("Query : " + getUserInfo);
			AppLoger.APPLOGGER.info("Query Count function: " + 101);
			SqlRowSet set = mssqlTemplate.queryForRowSet(getUserInfo, new Object[] { syntelID, 1 });
			AppLoger.APPLOGGER.info("Query Status: " + !set.wasNull());
			while (set.next()) {
				AppLoger.APPLOGGER.info("Name : " + set.getString("EMP_NAME"));
				deliveryDirectorName = set.getString("EMP_NAME");

				deliveryDirectorDetails.add(set.getString("EMP_NAME"));
				deliveryDirectorDetails.add(set.getString("EMP_NAME"));
				/* deliveryDirectorID = set.getString("DD_ID"); */
			}
			AppLoger.APPLOGGER.info("deliveryDirectorName : " + deliveryDirectorName);

		} catch (Exception e) {
			e.printStackTrace();
		}
		return deliveryDirectorDetails;

	}

