	@Override
	public ResponseEntity<Object> getDealDetails(String crmDealId, int rpVrsId) {
		System.out.println(
				"*****************************************************************==============rpVrsId=" + rpVrsId);
		Session session = this.sessionFactory.getCurrentSession();
		AppLoger.APPLOGGER.info("Query Count function: " + 105);
		try {
			
			AppLoger.APPLOGGER.info("RightPriceRepositoryImpl -- view Deal Creation Details");
			String getDealDetails = "select rpcm.CRM_Deal_Id,rpcm.Client_RC_Id,rpcm.Deal_Description,rpcm.Deal_Start_Date, rpcm.Deal_End_Date, rpdl.FP_Project_Type_Id AS FP_Type , rpcm.Deal_Type_Id,"
					+ " cust.customer_Name as customer_Name,mcode.Description as currency,mcodes.Description as DealStatus,"
					+ " Percentage_Close,mStage.Description as stages, cast(round(rpdl.Penalty_Percent,2) as numeric(36,2)) as Penalty_Percent, cast(round(rpdl.Deal_TCV,2) as numeric(36,2)) as Deal_TCV , "
					+ "rpdl.Deal_Version as Deal_Version,rpdl.Project_Industry,rpdl.Estimated_Revenue,rpdl.GM_Percentage,rpdl.Expected_Onsite_Percentage,rpdl.Expected_Offshore_Percentage,rpdl.Current_Approval_Level,rpdl.Current_Approval_Status "
					+ " from [synprod].[RP_Deal_CRM_Stage] as rpcm "
					+ "join synprod.MST_RP_Customer as cust on rpcm.Customer_Id = cust.Customer_Id "
					+ "join [synprod].[MST_RP_App_Code] as mcode on rpcm.Currency_Id = mcode.Code_Name "
					+ "join [synprod].[MST_RP_App_Code] as mcodes on rpcm.Deal_Status = mcodes.Code_Name "
					+ "join [synprod].[MST_RP_App_Code] as mStage on rpcm.Stage_Id = mStage.Code_Name "
					+ "join [synprod].[RP_Deal] as rpdl on  rpcm.CRM_Deal_Id = rpdl.CRM_Deal_Id "
					+ "where rpcm.CRM_Deal_Id=? and mcode.Code_Type='Currency' "
					+ " and mcodes.Code_Type='Deal_Status' and mStage.Code_Type='Deal_Stage' "
					+ " and rpdl.RP_Deal_Version_Id= '" + rpVrsId + "'  ";
			// System.out.println("**********************getDealDetails=============="+getDealDetails);
			Query quer = session.createSQLQuery(getDealDetails).addEntity(DealDetailsView.class);
			// System.out.println("**********************quer=============="+quer);
			quer.setParameter(0, crmDealId);
			
			List dealDetailsInfoList = quer.list();
			for (Object object : dealDetailsInfoList) {
				DealDetailsView dealDetailsInfo = (DealDetailsView) object;
				AppLoger.APPLOGGER.info("Deal Deatils are  " + dealDetailsInfo.getCustomerName() + "________"
						+ dealDetailsInfo.getDealDescription()+"_______________________" + dealDetailsInfo.getCurrentApprovalStatus());
			}
			if (!dealDetailsInfoList.isEmpty()) {
				return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(dealDetailsInfoList);
			} else {
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body(dealDetailsInfoList);
			}
		} catch(Exception e) {
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently We are facing technical issues, please try again later."+e.getMessage());
		} finally {
			//session.close();
		}
	}
