	@Override
	public ResponseEntity<Object> downloadFile(int objectId) {
		Session session = this.sessionFactory.getCurrentSession();
		AppLoger.APPLOGGER.info("Query Count function: " + 107);
		try {
			Criteria cr = session.createCriteria(FileUpload.class, "uploadedDocuments")
					.add(Restrictions.eq("objectid", objectId)).add(Restrictions.eq("activeStatus", 1));
			List fileData = cr.list();
			FileUpload fileDetails = (FileUpload) fileData.get(0);
			ByteArrayOutputStream bos = new ByteArrayOutputStream();
			ObjectOutput out = null;
			try {
				for (Object object : fileData) {
					FileUpload f = (FileUpload) object;
					out = new ObjectOutputStream(bos);
					out.writeObject(f.getData());
					out.flush();
					byte[] bytearr = bos.toByteArray();
				}
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (!fileData.isEmpty()) {
				return ResponseEntity.status(200)
						.header("Content-disposition", "attachment; filename=" + fileDetails.getOriginalFileName())
						.contentType(MediaType.parseMediaType("application/octet-stream")).body(fileDetails.getData());
			} else {
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN)
						.body("Currently We are facing technical issues, please try again later.");
			}
		} catch(Exception e) {
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently We are facing technical issues, please try again later."+e.getMessage());
		} finally {
			//session.close();
		}
	}

