	@Override
	public ResponseEntity<Object> save(ArrayList<RPRateCardRoles> rpRateCardRoles) {
		int insertId = 0;
		int updateId = 0;
		int rateCardId = 0;
		int rateCardCount = 0;
		Session session = this.sessionFactory.getCurrentSession();
		Session sessionUpdate = this.sessionFactory.getCurrentSession();
		AppLoger.APPLOGGER.info("Query Count function: " + 136);
		String cratedbyDas="";
		try {
			Query query = session.createQuery(
					"update RPRateCardRoles set activeStatus = :activeStatus, lastUpdatedBy = :lastUpdatedBy, lastUpdatedOn = :lastUpdatedOn where rcId = :rcId");
			for (RPRateCardRoles delRateCard : rpRateCardRoles) {
				cratedbyDas=delRateCard.getLastUpdatedBy();
				query.setParameter("activeStatus", 0);
				query.setParameter("lastUpdatedBy", delRateCard.getLastUpdatedBy());
				query.setParameter("lastUpdatedOn", delRateCard.getLastUpdatedOn());
				query.setParameter("rcId", delRateCard.getRcId());
			}
			updateId = query.executeUpdate();
		
			
			Query updateExistingRateCards = session
					.createQuery("Delete from RateCardManualMarginCal where RC_Id=:RC_Id");
			updateExistingRateCards.setParameter("RC_Id", rpRateCardRoles.get(0).getRcId());
			int updatedDealLCount1 = updateExistingRateCards.executeUpdate();
			
			AppLoger.APPLOGGER.info("saving policy details" + rpRateCardRoles.toString());
			for (RPRateCardRoles currRateCard : rpRateCardRoles) {
				if (currRateCard.getRcId() != 0) {
					rateCardId = currRateCard.getRcId();
					insertId = (int) session.save(currRateCard);
					AppLoger.APPLOGGER.info("rate card insert id : " + insertId);
					
				}
			}
			
			int a = rateCardOrDealCheckForOtherPages(rateCardId, 1, 2);
			AppLoger.APPLOGGER.info("value of a------------" + a);
			int storeProcResult = 0;
			if (insertId > 0) {
				/*
				 * call Store procedure for
				 */
				AppLoger.APPLOGGER.info(
						"_____________________________Testing store prcedure call__________________________________________________________________________________________");
				
				Query storeProcQuery = session
						.createSQLQuery(
								"{CALL synprod.RP_Calculate_Role_Wise_Yearly_GM_Revenue_Cost_For_Rate_Card(:rcId,:createdBy)}")
						.setParameter("rcId", rateCardId).setParameter("createdBy",cratedbyDas);
				
				List result = storeProcQuery.list();
				AppLoger.APPLOGGER.info("RESULT");
				AppLoger.APPLOGGER.info(result);
				storeProcResult = result.indexOf("SUCCESS");
				/*
				 * for(int i=0; i<result.size(); i++){ stock = (Stock)result.get(i);
				 * AppLoger.APPLOGGER.info(stock.getStockCode()); }
				 */
				
				AppLoger.APPLOGGER.info(
						"_____________________________Testing store prcedure call complete_________________________________________________________________________________");
			}
			if (insertId > 0 && a > 0 && storeProcResult == 0) {
				
				System.out.println("inside if-------------------");
				sessionUpdate.beginTransaction();
				Query q = sessionUpdate.createSQLQuery(
						"update synprod.RP_TRN_Page_Tracker set No_of_submitted_pages =:noOfSubmittedPages,  UPDATED_BY =:updatedBy , UPDATED_ON =:updatedOn where RC_or_Deal_ID =:rcIdOrDealId and Record_Type =:recordType and IS_ACTIVE =1");
				q.setParameter("noOfSubmittedPages", 2);
				q.setParameter("rcIdOrDealId", a);
				q.setParameter("recordType", 1);
				q.setParameter("updatedBy", auditTrails.getCurrentUser());
				q.setParameter("updatedOn", auditTrails.getCurrentTimeStamp());
				q.executeUpdate();
				sessionUpdate.getTransaction().commit();
				
				return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN)
						.body("Rate Card details saved successfully.");
				
			} else {
				
				if (a == 0) {
					return ResponseEntity.status(204).contentType(MediaType.TEXT_PLAIN)
							.body("Please submit previous page.");
				} else {
					return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN)
							.body("Currently We are facing technical issues, please try again later.");
				}
			}
		} catch (Exception e) {
			AppLoger.APPLOGGER.info("Error:" + e.getMessage());
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently Facing technical issue");
		} finally {
			//session.close();
			//sessionUpdate.close();
		}
	}

	public int rateCardOrDealCheckForOtherPages(int insertId, int recordType, int currentPage) {
		Session session = this.sessionFactory.getCurrentSession();
		AppLoger.APPLOGGER.info("Query Count function: " + 137);
		Criteria cr = session.createCriteria(PageTracker.class).add(Restrictions.eq("recordType", recordType))
				.add(Restrictions.eq("rcIdOrDealId", insertId)).add(Restrictions.eq("isActive", 1));
		List al = cr.list();
		int a = 0;
		if (!al.isEmpty()) {
			a = insertId;
		}
		return a;
	}

	@Override
	public ResponseEntity<Object> searchRateCardData(String searchRoles) {
		
		Session session = this.sessionFactory.getCurrentSession();
		try {
			AppLoger.APPLOGGER.info("Entity List :::::::::::::::::::::::::::::::::::::::" + searchRoles);
			AppLoger.APPLOGGER.info("Query Count function: " + 138);
			String[] searchArr = searchRoles.split("\\s+");
			AppLoger.APPLOGGER.info("length : " + searchArr.length + " content : " + searchArr);
			String whereCondition = " WHERE MASTER_ROLE_LONG_DESCRIPTION LIKE '%" + searchArr[0] + "%' and MR.Is_Active=1 or  X0_Skill_Element_Description like '%" + searchArr[0] + "%' and  MR.Is_Active=1";
			if (searchArr.length > 1) {
				for (int i = 1; i < searchArr.length; i++) {
					whereCondition += " AND Master_Role_Long_Description like '%" + searchArr[i] + "%'and MR.Is_Active=1  or  X0_Skill_Element_Description like '%" + searchArr[i] + "%' and MR.Is_Active=1";
				}
			}
			
			String get_entity = "SELECT MASTER_ROLE_ID,MR.Master_Role_Short_Description,MR.Master_Role_Long_Description,MR.Proficiency_level_Id,MR.X0_Proficiency_Id,MR.Proficiency_Level_Description,MR.GCM_CODE,MR.X0_Proficiency_Description,MR.Band_Grade, SP.Sub_Practice_Id,SP.Sub_Practice_Name,PR.Description as Practice_Name,MSR.SYNTEL_ROLE_ID,MSR.SYNTEL_ROLE_NAME,MR.Skill_Complexity_Desc,MR.X0_Skill_Description,MR.X0_Skill_Element_Description  "  
					
					+ " FROM synprod.MST_RP_Master_Roles as MR "
					+ "JOIN synprod.MST_RP_Sub_Practice as SP on MR.Sub_Practice_Id = SP.Sub_Practice_Id "
					+ "JOIN synprod.MST_RP_Practice as PR on SP.Practice_id = PR.Practice_Id "
					+ "JOIN synprod.MST_RP_Syntel_Roles AS MSR ON MR.Syntel_Role_Id=MSR.Syntel_Role_Id " + whereCondition +" and PR.Is_Active=1 ";
			
			AppLoger.APPLOGGER.info("Search query : " + get_entity);
			Query quer = session.createSQLQuery(get_entity).addEntity(MstRpMasterRolesSearch.class);
			AppLoger.APPLOGGER.info("serchArr length:" + searchArr.length);
			
			List entityList = quer.list();
			AppLoger.APPLOGGER.info("Entity List :");
			for (Object object : entityList) {
				MstRpMasterRolesSearch mstRoleSearchSelection = (MstRpMasterRolesSearch) object;
				AppLoger.APPLOGGER.info("Long Description  : " + mstRoleSearchSelection.getMasterRoleLongDescription());
				AppLoger.APPLOGGER.info("Skill Complexity  : " + mstRoleSearchSelection.getSkillComplexityDesc());
				AppLoger.APPLOGGER.info("Skill Description  : " + mstRoleSearchSelection.getX0SkillDescription());
			}
			
			if (!entityList.isEmpty()) {
				return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(entityList);
			} else {
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body(entityList);
			}
		}catch (Exception e) {
			AppLoger.APPLOGGER.info("Error:" + e.getMessage());
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently Facing technical issue");
		} finally {
			//session.close();
		}

		// return searchRoles;

	}
	
