	private boolean isVisaExists(VisaLabels visaDetailsAdd) {
		Session session = this.sessionFactory.getCurrentSession();
		AppLoger.APPLOGGER.info("Query Count function: " + 146);
		try {
			
			Query query = session.createQuery("from VisaLabels where visaTypeId = :visaTypeId and countryId= :countryId and isActive = 1");
			query.setParameter("visaTypeId", visaDetailsAdd.getVisaTypeId());
			query.setParameter("countryId", visaDetailsAdd.getCountryId());
			List list = query.list();
			AppLoger.APPLOGGER.info("Size:" + list.size());
			return (list.size() >= 1) ? true : false;
		} catch (Exception hb) {
			AppLoger.APPLOGGER.info("Exception:--------------" + hb);
			return false;

		} finally {
			//session.close();
		}
	}
	
