	// updating the approval details after sending for approval.
	@Override
	public ResponseEntity<Object> updateApprovalDetails(RateCardDetails rateCardApproval) {
		int updateId = 0;
		Session session = this.sessionFactory.getCurrentSession();
		AppLoger.APPLOGGER.info("Query Count function: " + 150);
		try 
		{
			//session.beginTransaction();
			String status ="";
			String isRcType = "";
			Integer intIsItKpo = 0; 
			Criteria check =session.createCriteria(RateCardDetails.class, "rc").add(Restrictions.eq("rcId", rateCardApproval.getRcId()));
			List<RateCardDetails> ratecDetails = check.list();
			
			for(RateCardDetails getRcDetail:ratecDetails)
			{
				status = getRcDetail.getStatusIndicator();
				isRcType= getRcDetail.getIsManualRc();
				intIsItKpo = getRcDetail.getIsItKpo();
			}
			
			Query query = session.createQuery(
					"update RateCardDetails set approvalFlagLevel = :approvalFlagLevel,rainbowApprovalFlag=:rainbowApprovalFlag,"
					+ "currentApprovalStatus = :currentApprovalStatus, currentApproverId = :currentApproverId,currentApprovalLevel = :currentApprovalLevel, "
					+ "updatedBy = :updatedBy, updatedOn = :updatedOn, approverComments= :approverComments, statusIndicator= :statusIndicator"
					+ ", updateAtosEmailId =:updateAtosEmailId, updateEmployeeName =:updateEmployeeName where rcId = :rcId");
			query.setParameter("approvalFlagLevel", rateCardApproval.getApprovalFlagLevel());
			query.setParameter("rainbowApprovalFlag", rateCardApproval.getRainbowApprovalFlag());
			query.setParameter("currentApprovalStatus", rateCardApproval.getCurrentApprovalStatus());
			query.setParameter("currentApproverId", rateCardApproval.getCurrentApproverId());
			query.setParameter("currentApprovalLevel", rateCardApproval.getCurrentApprovalLevel());
			query.setParameter("updatedBy", rateCardApproval.getUpdatedBy());
			query.setParameter("updatedOn", rateCardApproval.getUpdatedOn());
			query.setParameter("approverComments", rateCardApproval.getApproverComments());
			query.setParameter("statusIndicator", rateCardApproval.getStatusIndicator());
			query.setParameter("updateAtosEmailId", rateCardApproval.getUpdateAtosEmailId());
			query.setParameter("updateEmployeeName", rateCardApproval.getUpdateEmployeeName());
			query.setParameter("rcId", rateCardApproval.getRcId());
			updateId = query.executeUpdate();
			
			// RC manual upload, insert Rate card roles and update Revised rates in case of IT only.
			if(rateCardApproval.getCurrentApprovalStatus() == 2 && intIsItKpo == 1 
					&& (rateCardApproval.getIsManualRc().equals("M")||(rateCardApproval.getIsManualRc().equals("H"))))
			{	
				AppLoger.APPLOGGER.info("Inside RightPriceRepositoryImplementaion ==> updateApprovalDetails ==> Calling stored procedure [synprod].[RP_SaveRateCardRoles]");
				Query qrySaveRoles = session.createSQLQuery("{CALL [synprod].[RP_SaveRateCardRoles_NonGFT](:RC_Id)}");
				qrySaveRoles.setParameter("RC_Id",  rateCardApproval.getRcId());
				int qryRows = qrySaveRoles.executeUpdate();
				AppLoger.APPLOGGER.info("Executed Rows from Stored Procedure [synprod].[RP_SaveRateCardRoles_NonGFT] ****************"+qryRows);
				
				Query QryDetails = session.createQuery(
						"FROM RateCardLocation WHERE Country_Id IN (select baseCountryId from RateCardCurrencyUtilization "
						+ "where rcId = :rcId AND  rateCardProcessingType = :rateCardProcessingType AND Is_Active = :Is_Active) AND rcId = :rcId AND Is_Active = :Is_Active");
				
				QryDetails.setParameter("rcId", rateCardApproval.getRcId());
				QryDetails.setParameter("rateCardProcessingType", 1);
				QryDetails.setParameter("Is_Active", 1);
				List<RateCardLocation> lstRCLocation = QryDetails.list();
												
				/*Criteria crtGetCountries = session.createCriteria(RateCardLocation.class).add(Restrictions.eq("isActive", 1)).add(Restrictions.eq("rcId",rateCardApproval.getRcId()));
				List<RateCardLocation> lstRCLocation = crtGetCountries.list();
				//Integer manualUploadId = (Integer)getManualUploadId.;*/
				for(RateCardLocation objRCLOcation : lstRCLocation) 
				{						
					int intCountryId =  objRCLOcation.getCountryId();
					int intCityId = objRCLOcation.getCityId();
					
					AppLoger.APPLOGGER.info("Inside RightPriceRepositoryImplementaion ==> updateApprovalDetails ==> Calling stored procedure [synprod].[RP_Update_Rate_Card_Roles_Wise_RCGM_Yearly_Summary]");
					Query qryUpdateSummary = session.createSQLQuery("{CALL [synprod].[RP_Calculate_Role_Wise_Yearly_GM_Revenue_Cost_For_Rate_Card_Manual](:RC_Id,:Country_Id,:City_Id,:strCreatedBy)}");
					qryUpdateSummary.setParameter("RC_Id",  rateCardApproval.getRcId());
					qryUpdateSummary.setParameter("Country_Id",  intCountryId);
					qryUpdateSummary.setParameter("City_Id",  intCityId);
					String syntelLanId= getSyntelId(this.auditTrails.getCurrentUser());
					if(syntelLanId.isEmpty() || syntelLanId==null)
					{
						qryUpdateSummary.setParameter("strCreatedBy", this.auditTrails.getCurrentUser());
					}
					else
					{
					qryUpdateSummary.setParameter("strCreatedBy", syntelLanId);
					}
					List lstResult = qryUpdateSummary.list();
					AppLoger.APPLOGGER.info("RESULT");
					AppLoger.APPLOGGER.info(lstResult);
					if(!lstResult.get(0).toString().toLowerCase().trim().equals("success"))
					{						
						//session.close();
						//return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently We are facing technical issues, please try again later.");
						throw new Exception("[RP_Calculate_Role_Wise_Yearly_GM_Revenue_Cost_For_Rate_Card_Manual] returned Failure");
						//return;
					}
				}
				
				// Call RP_UpdateRevisedRate
				AppLoger.APPLOGGER.info("Inside RightPriceRepositoryImplementaion ==> updateApprovalDetails "
						+ "==>Calling stored procedure [synprod].[RP_UpdateRevisedRates_NonGFT]");
				ProcedureCall qryUpdateRates = session.createStoredProcedureCall("[synprod].[RP_UpdateRevisedRates_NonGFT]");
				qryUpdateRates.registerParameter("RC_Id", Integer.class, ParameterMode.IN).bindValue(rateCardApproval.getRcId());
				String syntelLanId= getSyntelId(this.auditTrails.getCurrentUser());
				if(syntelLanId.isEmpty() || syntelLanId==null)
				{
					qryUpdateRates.registerParameter("strUpdatedBy", String.class, ParameterMode.IN).bindValue(this.auditTrails.getCurrentUser());
				}
				else
				{
				qryUpdateRates.registerParameter("strUpdatedBy", String.class, ParameterMode.IN).bindValue(syntelLanId);
				}
				ProcedureOutputs procedureResult = qryUpdateRates.getOutputs();// Update rates
					
			}
			
			RateCardTest rcDetail=null;
	           Criteria crit = session.createCriteria(RateCardTest.class, "rc").add(Restrictions.eq("rcId", rateCardApproval.getRcId()));
				List<RateCardTest> rateCardAfterProc = crit.list();
				for (Object objects : rateCardAfterProc) {
					 rcDetail = (RateCardTest)objects;
					
				}
						
			if(rateCardApproval.getCurrentApprovalStatus() == 3 || rateCardApproval.getCurrentApprovalStatus() == 2) 
			{
				if(status==null)
				{
					if(isRcType.equals("M"))
					{
						sendMails(12,rateCardApproval.getRcId(),session,rateCardApproval.getApproverComments(),status,rateCardApproval,rcDetail);
					}
					else if(isRcType.equals("A"))
					{
						sendMails(5, rateCardApproval.getRcId(),session,rateCardApproval.getApproverComments(),status,rateCardApproval,rcDetail);
					}
					else if(isRcType.equals("H"))
					{
						sendMails(5, rateCardApproval.getRcId(),session,rateCardApproval.getApproverComments(),status,rateCardApproval,rcDetail);
					}
				}
				else if(status.equals("DRAFT"))
				{
					
					sendMails(5, rateCardApproval.getRcId(),session,rateCardApproval.getApproverComments(),status,rateCardApproval,rcDetail);
				}
				
				else if(status.equals("GFT")){
					sendMails(12,rateCardApproval.getRcId(),session,rateCardApproval.getApproverComments(),status,rateCardApproval,rcDetail);
				}
				else 
				{
					sendMails(5, rateCardApproval.getRcId(),session,rateCardApproval.getApproverComments(),status,rateCardApproval,rcDetail);
				}
			}
			else if(rateCardApproval.getCurrentApprovalStatus() == 4)
			{
				if(status.equals("GFT"))
				{
					sendMails(18,rateCardApproval.getRcId(),session,rateCardApproval.getApproverComments(),status,rateCardApproval,rcDetail);
				}
				else{
					sendMails(5, rateCardApproval.getRcId(),session,rateCardApproval.getApproverComments(),status,rateCardApproval,rcDetail);
				}
			}
			
			AppLoger.APPLOGGER.info("data for rc updated----------------------------------------" + updateId);
			if (updateId > 0) 
			{
				//session.getTransaction().commit();
				return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body("Successfully Sent For Approval.");
			} 
			else 
			{
				//session.getTransaction().rollback();
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN)
						.body("Currently We are facing technical issues, please try again later.");
			}
		} 
		catch(Exception e)  
		{
			//session.getTransaction().rollback();
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN)
					.body("Currently We are facing technical issues, please try again later." +e.getMessage());
		} 
		finally
		{
			//session.close();
		}
	}

