	private List<Object> getEmpDetails(List empId) {
		List<Object> empIds = new ArrayList(empId);
		List<Object> empDetailList = new ArrayList<Object>();
		/*
		 * System.out.println("The EmpId in the list is.......... "+empId.get(1)
		 * +""+empId.get(2)+""+empId.get(3));
		 */
		try {
			for (Object id : empIds) {
				String getEmpData = "SELECT NAME,DAS_Id,DAS_Id,GRADE,CURRENT_DESG FROM [synprod].[MST_RP_EMP_INFORMATION_WITH_CONTRACT_EMPLOYEES] WHERE DAS_Id=?";
				SqlRowSet set = mssqlTemplate.queryForRowSet(getEmpData, new Object[] { id });
				while (set.next()) {
					HashMap<String, String> empDetails = new HashMap<>();
					AppLoger.APPLOGGER
							.info("Emp ID : " + set.getString("DAS_Id") + " " + "Name : " + set.getString("NAME"));
					empDetails.put("USERID", set.getString("DAS_Id"));
					empDetails.put("EMP_ID", set.getString("DAS_Id"));
					empDetails.put("EMP_NAME", set.getString("NAME"));
					empDetails.put("EMP_DESC", set.getString("CURRENT_DESG"));
					empDetailList.add(empDetails);
				}
			}
			AppLoger.APPLOGGER.info("Emp Details using User ID : " + empDetailList);
		} catch (Exception e) {
			e.printStackTrace();
		}
		return empDetailList;
	}

