	private boolean isCityShiftCostExists(OffshoreMiscellaneousCost miscellaneousCostAdd) {
		Session session = this.sessionFactory.getCurrentSession();
		Query query = session.createQuery("from OffshoreMiscellaneousCost where cityId = :cityId and isActive = 1");
		query.setParameter("cityId", miscellaneousCostAdd.getCityId());
		List list = query.list();
		AppLoger.APPLOGGER.info("Size:" + list.size());
		return (list.size() >= 1) ? true : false;
	};

