	private List<EmpDetails> getEmployee(List empId) {
		List<String> empIds = new ArrayList(empId);
		List<EmpDetails> emp = new ArrayList<EmpDetails>();
		AppLoger.APPLOGGER.info("Query Count function: " + 171);
		try {
			for (String id : empIds) {
				String getEmpData = "SELECT NAME,DAS_Id,DAS_Id,GRADE,CURRENT_DESG FROM [synprod].[MST_RP_EMP_INFORMATION_WITH_CONTRACT_EMPLOYEES] WHERE DAS_Id=?";
				SqlRowSet set = mssqlTemplate.queryForRowSet(getEmpData, new Object[] { id });
				while (set.next()) {
					EmpDetails empData = new EmpDetails();
					AppLoger.APPLOGGER
							.info("Emp ID : " + set.getString("DAS_Id") + " " + "Name : " + set.getString("NAME"));
					empData.setEmployeeLanId(set.getString("DAS_Id"));
					empData.setEmployeeId(set.getString("DAS_Id"));
					empData.setName(set.getString("NAME"));
					empData.setDesignation(set.getString("CURRENT_DESG"));
					emp.add(empData);
				}
			}
			AppLoger.APPLOGGER.info("Emp Details using User ID : " + emp);
		} catch (Exception e) {
			e.printStackTrace();
		}
		return emp;
	}

