	@Override
	public ResponseEntity<Object> uploadCountry(ArrayList<Country> countryBean) {
		AppLoger.APPLOGGER.info("@Repository*+-*+-*+*+*+*+*+*+-*");
		int insertId = 0;
		Session session = this.sessionFactory.getCurrentSession();
		try {
			
			for (Country countryData : countryBean) {
				boolean check = this.checkCountryName(countryData.getCountryName());
				AppLoger.APPLOGGER.info("Checking Country name:" + check);
				if (!check) {
					return ResponseEntity.status(203).contentType(MediaType.TEXT_PLAIN)
							.body(" Country Name    " + countryData.getCountryName() + "   is already exist.");
				}
				insertId = (int) session.save(countryData);
				AppLoger.APPLOGGER.info("file insertId : " + insertId);
			}
			if (insertId != 0) {
				//session.close();
				return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body("Data Inserted Successfully");
			} else {
				//session.close();
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN)
						.body("Currently We are facing technical issues, please try again later.");
			}
		} catch (Exception e) {
			//session.close();
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN)
					.body("Currently We are facing technical issues, please try again later.");
		}
	}

	private boolean checkCountryName(String countryName) {
		AppLoger.APPLOGGER.info("CountryDetails:" + countryName);
		Session session = this.sessionFactory.getCurrentSession();
		Query query = session.createQuery("from Country where countryName = :countryName");
		query.setParameter("countryName", countryName);
		List list = query.list();
		AppLoger.APPLOGGER.info("Size:" + list.size());
		if (list.size() >= 1) {
			return false;
		}
		return true;
	};

