	@Override
	public ResponseEntity<Object> onUpdateMasterRate(MasterRate masterRate) {
		int insertId = 0;
		Session session = this.sessionFactory.getCurrentSession();
		Transaction tc = session.beginTransaction();
		AppLoger.APPLOGGER.info("inside onUpdateMasterRate -----");
		Query query = session.createQuery("UPDATE MasterRate set rateLow = :rateLow,"
				+ "rateMedium = :rateMedium , rateHigh = :rateHigh , rateVHigh = :rateVHigh ,"
				+ "rateOffshore = :rateOffshore "
				+ "where transactionYear = :transactionYear and countryId = :countryId "
				+ "and masterRoleId = :masterRoleId and isActive = :isActive");
		query.setParameter("rateLow", masterRate.getRateLow());
		query.setParameter("rateMedium", masterRate.getRateMedium());
		query.setParameter("rateHigh", masterRate.getRateHigh());
		query.setParameter("rateVHigh", masterRate.getRateVHigh());
		query.setParameter("rateOffshore", masterRate.getRateOffshore());
		query.setParameter("transactionYear", masterRate.getTransactionYear());
		query.setParameter("countryId", masterRate.getCountryId());
		query.setParameter("masterRoleId", masterRate.getMasterRoleId());
		query.setParameter("isActive", 1);
		insertId = query.executeUpdate();
		AppLoger.APPLOGGER.info("updated successfully");
		tc.commit();
		//session.close();
		return null;
	}

