	@Override
	public ResponseEntity<Object> saveOnsiteCostData(FPDCRCAndProjectDetails hardWareCostData) {
		int insertId = 0;
		int count = 0;
		int updatedDealRolesCount = 0;
		Session session = this.sessionFactory.getCurrentSession();

		try {
			AppLoger.APPLOGGER.info("saveFPDealCreationRCAndProjectDetails ------->RepoImpl ");
			session.beginTransaction();

			for (RPDealHardwareSoftwareCost costDetails : hardWareCostData.getOnlineCostDetails()) {
				Query updateHardWareCostDetails = session
						.createQuery("update RPDealHardwareSoftwareCost set Is_Active =:Is_Active "
								+ "where rpDealVersionId= :rpVersionId AND countryId = :countryId AND cityId = :cityId AND towerId = :towerId");
				updateHardWareCostDetails.setParameter("Is_Active", 0);
				updateHardWareCostDetails.setParameter("rpVersionId", costDetails.getRpDealVersionId());
				updateHardWareCostDetails.setParameter("countryId", costDetails.getCountryId());
				updateHardWareCostDetails.setParameter("cityId", costDetails.getCityId());
				updateHardWareCostDetails.setParameter("towerId", costDetails.getTowerId());
				updatedDealRolesCount = updateHardWareCostDetails.executeUpdate();
			}
			for (RPDealHardwareSoftwareCost hardwareCost : hardWareCostData.getOnlineCostDetails()) {
				session.saveOrUpdate(hardwareCost);
				AppLoger.APPLOGGER.info("Hard Ware Cost id: " + hardwareCost.getHardwareCostId()
						+ "Hard Ware Cost Description" + hardwareCost.getHardwareCostDescription());
			}
			// Deleting the previous records on the transaction table
			for (RPDealRelocationDetails relocationDetails : hardWareCostData.getTravelRelocationCostDetails()) {
				Query updateRelocationDetails = session.createQuery("update RPDealRelocationDetails set Is_Active =:Is_Active "
						+ "where rpDealVersionId= :rpVersionId AND countryId = :countryId AND cityId = :cityId AND towerId = :towerId");
				updateRelocationDetails.setParameter("Is_Active", 0);
				updateRelocationDetails.setParameter("rpVersionId", relocationDetails.getRpDealVersionId());
				updateRelocationDetails.setParameter("countryId", relocationDetails.getCountryId());
				updateRelocationDetails.setParameter("cityId", relocationDetails.getCityId());
				updateRelocationDetails.setParameter("towerId", relocationDetails.getTowerId());
				updatedDealRolesCount = updateRelocationDetails.executeUpdate();
			}

			// Inserting the data in the Relocation Details..
			for (RPDealRelocationDetails relocationCost : hardWareCostData.getTravelRelocationCostDetails()) {
				session.saveOrUpdate(relocationCost);
				AppLoger.APPLOGGER.info("Relocation Description is.: " + relocationCost.getRelocationDescription()
						+ "Relocation cost id" + relocationCost.getDealRelocationCostId());
			}

			// end

			session.getTransaction().commit();

		} catch (Exception e) {
			session.getTransaction().rollback();
			//session.close();
			AppLoger.APPLOGGER.info("Exc----------------> " + e);
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN)
					.body("Currently We are facing technical issues, please try again later.");
		}
		//session.close();
		return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body("inserted successfully");
	}

