	@Override
	public ResponseEntity<Object> uploadMannualRC(ArrayList<RateCardRolesSTG> arrLiRcRolesSTG) {
		Session session = this.sessionFactory.getCurrentSession();
		AppLoger.APPLOGGER.info("Inside RightPriceRepositoryImplementaion ==> uploadMannualRC"); 
		try
		{
			session.beginTransaction();
			
			//AppLoger.APPLOGGER.info("Now trying to call the Stored Procedure : RP_Insert_Rate_Card_Roles_STG *****************");
			// to delete records from stg
			
			int intRateCardDelId = 0;
			Query strDeleteQuery = session.createQuery("delete from RateCardRolesSTG where rcId=:rcId");
			strDeleteQuery.setParameter("rcId", arrLiRcRolesSTG.get(0).getRcId());
			intRateCardDelId = strDeleteQuery.executeUpdate();
			System.out.println("The Id for deleting the data is.......  "+ intRateCardDelId);

			for (RateCardRolesSTG objRcRolesSTG : arrLiRcRolesSTG) 
			{
				Query exQuery = session.createSQLQuery("{CALL synprod.RP_Insert_Rate_Card_Roles_STG(:RC_Id,:strCountryDesc,:strCityDesc,:strPracticeDesc,:strSubPracticeDesc,:strMasterRoleDesc,"
				        + ":strProficiencyDesc,:strBandDesc,:strGradeDesc,:strSkillDesc,:strSkillElementDesc,:strKnowledgeDesc,:strBandGradeDesc,"
				        //:X.O Proficiency,
				        + ":strClientRole,:intLocalPercentge,:intDeputedPercentage,:decOnsiteCustRate,:intOnsiteUsage,:decOffshoreCustRate,:intOffshoreUsage,"
				        /*+ ":intYear2,:intYear3,:intYear4,:intYear5,:strCreatedBy,:strUpdatedBy)}");*/
				        + ":intTransactionYear,:strCreatedBy,:strUpdatedBy)}");
				exQuery.setParameter("RC_Id", objRcRolesSTG.getRcId());
				exQuery.setParameter("strCountryDesc", objRcRolesSTG.getCountry().toLowerCase());
				exQuery.setParameter("strCityDesc", objRcRolesSTG.getCity().toLowerCase());
				exQuery.setParameter("strPracticeDesc", objRcRolesSTG.getPractice().toLowerCase());
				exQuery.setParameter("strSubPracticeDesc", objRcRolesSTG.getSubPractice().toLowerCase());
				exQuery.setParameter("strMasterRoleDesc", objRcRolesSTG.getRole().toLowerCase());
				exQuery.setParameter("strProficiencyDesc", objRcRolesSTG.getProficiencyDesc().toLowerCase());
				exQuery.setParameter("strBandDesc", objRcRolesSTG.getBand().toLowerCase());
				exQuery.setParameter("strGradeDesc", objRcRolesSTG.getGrade().toLowerCase());
				exQuery.setParameter("strSkillDesc", objRcRolesSTG.getxOSkills().toLowerCase());
				exQuery.setParameter("strSkillElementDesc", objRcRolesSTG.getxOSkillsElement().toLowerCase());
				exQuery.setParameter("strKnowledgeDesc", objRcRolesSTG.getxOKnowledge());
				exQuery.setParameter("strBandGradeDesc", objRcRolesSTG.getxOBandGrade().toLowerCase());
				exQuery.setParameter("strClientRole", objRcRolesSTG.getClientRole().toLowerCase());
				exQuery.setParameter("intLocalPercentge", objRcRolesSTG.getLocalPercentage());
				exQuery.setParameter("intDeputedPercentage", objRcRolesSTG.getDeputedPercentage());
				exQuery.setParameter("decOnsiteCustRate", objRcRolesSTG.getOnsiteCustomerRate());
				exQuery.setParameter("intOnsiteUsage", objRcRolesSTG.getOnsiteUsage());
				exQuery.setParameter("decOffshoreCustRate", objRcRolesSTG.getOffshoreCustomerRate());
				exQuery.setParameter("intOffshoreUsage", objRcRolesSTG.getOffshoreUsage());
				exQuery.setParameter("intTransactionYear", objRcRolesSTG.getTransactionYear());
				/*exQuery.setParameter("intYear3", objRcRolesSTG.getYear3Usage());
				exQuery.setParameter("intYear4", objRcRolesSTG.getYear4Usage());
				exQuery.setParameter("intYear5", objRcRolesSTG.getYear5Usage());*/
				exQuery.setParameter("strCreatedBy", objRcRolesSTG.getCreatedBy());
				exQuery.setParameter("strUpdatedBy", objRcRolesSTG.getUpdatedBy());

				int exRows = exQuery.executeUpdate();
				AppLoger.APPLOGGER.info("Executed Rows from Stored Procedure****************"+exRows);
			}
			
			AppLoger.APPLOGGER.info("Inside RightPriceRepositoryImplementaion ==> uploadMannualRC ==> Calling stored procedure [synprod].[RP_SaveRateCardRoles]");
			Query qrySaveRoles = session.createSQLQuery("{CALL [synprod].[RP_SaveRateCardRoles](:RC_Id)}");
			qrySaveRoles.setParameter("RC_Id",  arrLiRcRolesSTG.get(0).getRcId());
			int qryRows = qrySaveRoles.executeUpdate();
			AppLoger.APPLOGGER.info("Executed Rows from Stored Procedure [synprod].[RP_SaveRateCardRoles] ****************"+qryRows);
			
			
			AppLoger.APPLOGGER.info("Inside RightPriceRepositoryImplementaion ==> uploadMannualRC ==> Calling stored procedure [synprod].[RP_Update_Rate_Card_Roles_Wise_RCGM_Yearly_Summary]");
			Query qryUpdateSummary = session.createSQLQuery("{CALL [synprod].[RP_Update_Rate_Card_Roles_Wise_RCGM_Yearly_Summary](:RC_Id,:strCreatedBy)}");
			qryUpdateSummary.setParameter("RC_Id",  arrLiRcRolesSTG.get(0).getRcId());
			qryUpdateSummary.setParameter("strCreatedBy",  arrLiRcRolesSTG.get(0).getCreatedBy());
			
			List result = qryUpdateSummary.list();
			AppLoger.APPLOGGER.info("RESULT");
			AppLoger.APPLOGGER.info(result);
			if(!result.get(0).toString().toLowerCase().trim().equals("success"))
			{
				session.getTransaction().rollback();
				//session.close();
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently We are facing technical issues, please try again later.");
			}

			AppLoger.APPLOGGER.info("Executed Rows from Stored Procedure [synprod].[synprod].[RP_Update_Rate_Card_Roles_Wise_RCGM_Yearly_Summary] ****************"+qryRows);
			
			session.getTransaction().commit();
			//session.close();
			return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body("Data Inserted Successfully");
		}
		catch(HibernateException ex)
		{
			session.getTransaction().rollback();
			//session.close();		
			String strError = ex.getCause().getMessage();
			throw ex;
		}		
	}
