	@Override
	public ResponseEntity<Object> updateApprovalDataForDeal(Deal dealDetails) {
		int updateId = 0;
		int rpVersionId=0;
		int currentapprovalstatus=0;
		int storeProcResultProc =0;
		
		Session session = this.sessionFactory.getCurrentSession();
		try {
			
			Query query = session.createQuery(
					"update Deal set statusIndicator = :statusIndicator, currentApprovalStatus = :currentApprovalStatus, currentApproverId = :currentApproverId, currentApproverRoleId = :currentApproverRoleId ,"
					+ "approverComments = :approverComments, currentApprovalLevel = :currentApprovalLevel, updatedBy = :updatedBy, updatedDate = :updatedDate"
					+ ", updateAtosEmailId =:updateAtosEmailId, updateEmployeeName =:updateEmployeeName where rpDealVersionId = :rpDealVersionId AND isActive = 1");
			query.setParameter("statusIndicator", dealDetails.getStatusIndicator());
			query.setParameter("currentApprovalStatus", dealDetails.getCurrentApprovalStatus());
			query.setParameter("currentApproverId", dealDetails.getCurrentApproverId());
			query.setParameter("currentApproverRoleId", dealDetails.getCurrentApproverRoleId());
			query.setParameter("approverComments", dealDetails.getApproverComments());
			query.setParameter("currentApprovalLevel", dealDetails.getCurrentApprovalLevel());
			query.setParameter("updatedBy", dealDetails.getUpdatedBy());
			query.setParameter("updatedDate", dealDetails.getUpdatedDate());
			query.setParameter("updateAtosEmailId", dealDetails.getUpdateAtosEmailId());
			query.setParameter("updateEmployeeName", dealDetails.getUpdateEmployeeName());
			query.setParameter("rpDealVersionId", dealDetails.getRpDealVersionId());
			updateId = query.executeUpdate();
			currentapprovalstatus=dealDetails.getCurrentApprovalStatus();
			rpVersionId=dealDetails.getRpDealVersionId();
			
			if(currentapprovalstatus == 3)
			{
				Query storeProcQuery = session.createSQLQuery("{CALL synprod.Proc_ApprovedDeal_to_OldDealTable(:rpDealVersionId)}")
						.setParameter("rpDealVersionId", rpVersionId);
				List result = storeProcQuery.list();
				AppLoger.APPLOGGER.info("RESULT");
				AppLoger.APPLOGGER.info(result);
				storeProcResultProc = result.indexOf("SUCCESS");
			}
			
			if(dealDetails.getCurrentApprovalStatus()==2) 
			{
				
				sendMailTM(1,dealDetails.getRpDealVersionId(),session,dealDetails.getUpdatedBy(),dealDetails.getCurrentApproverId());
			}
			
			else if(dealDetails.getCurrentApprovalStatus()==4) 
			{
				
				sendMailTM(2,dealDetails.getRpDealVersionId(),session,dealDetails.getUpdatedBy(),dealDetails.getCurrentApproverId());
			}
			
			else if(dealDetails.getCurrentApprovalStatus()==3) 
			{
				
				sendMailTM(3,dealDetails.getRpDealVersionId(),session,dealDetails.getUpdatedBy(),dealDetails.getCurrentApproverId());
			}
			
			
			AppLoger.APPLOGGER.info("data for rc updated----------------------------------------" + updateId);
			if (updateId > 0) {
				return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(200);
			} else {
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body(205);
			}
		} catch (Exception e) {
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body(205);
		} finally {
			//session.close();
		}
	}

