	@Override
	public ResponseEntity<Object> updateTaxParam(Deduction[] deduction) {
		int insertId = 0;
		Session session = this.sessionFactory.getCurrentSession();
		Transaction tc = session.beginTransaction();
		for (Deduction updateDeduction : deduction) {
			AppLoger.APPLOGGER.info("data  - - - - - - - - -");
			AppLoger.APPLOGGER.info("para : " + updateDeduction.getParDeduction());
			AppLoger.APPLOGGER.info("visa" + updateDeduction.getVisaTypeId());
			AppLoger.APPLOGGER.info("country : " + updateDeduction.getCountryId());
			AppLoger.APPLOGGER.info("year : " + updateDeduction.getYear());
			AppLoger.APPLOGGER.info("deduc type : " + updateDeduction.getDeductionTypeId());
			AppLoger.APPLOGGER.info("active : " + updateDeduction.getIsActive());
			Query query = session.createQuery("UPDATE Deduction set parDeduction = :parDeduction,"
					+ "isActive = :isActive "
					+ "where year = :year and countryId = :countryId and deductionTypeId = :deductionTypeId and visaTypeId = :visaTypeId and deductionCatId =:deductionCatId");
			query.setParameter("parDeduction", updateDeduction.getParDeduction());
			query.setParameter("isActive", updateDeduction.getIsActive());
			query.setParameter("year", updateDeduction.getYear());
			query.setParameter("countryId", updateDeduction.getCountryId());
			query.setParameter("deductionTypeId", updateDeduction.getDeductionTypeId());
			query.setParameter("visaTypeId", updateDeduction.getVisaTypeId());
			query.setParameter("deductionCatId", 2);
			insertId = query.executeUpdate();
		}
		AppLoger.APPLOGGER.info("updated successfully");
		tc.commit();
		//session.close();
		return null;
	}
	
