	@Override
	public ResponseEntity<Object> uploadManualRateCard(MultipartFile file, String fileName,
			InputStream uploadedInputStream, FileObjectTable fileObj,FPManualDealAttachment fpData, int countryId) 
	{
		int manualUploadId = 0;
		AppLoger.APPLOGGER.info("@Repository*+-*+-*+*+*+*+*+*+-*");
		Session session = this.sessionFactory.getCurrentSession();
        try 
        {
        	//session.beginTransaction();
        	
			// File Writing to D Disk
			byte[] byteArrayString = file.getBytes();
			File file1 = null;
			String newFileName = "";
			ByteArrayInputStream ba = new ByteArrayInputStream(byteArrayString);
			System.out.println("converting to byteInpurtStream");
			File files = new File("D:\\FTP\\Rightprice\\Ratecard\\");
			System.out.println("snapbill present is " + files.exists());
			if (!files.exists()) 
			{
				if (files.mkdirs()) 
				{
					System.out.println("Snapbill directories are created!");
				} 
				else 
				{
					System.out.println("Already Present!");
				}
			}
			FileOutputStream outputStream = null;
			
			String[] fileNameSplit = new String[100];
			String modifiedFileName = file.getOriginalFilename();
			AppLoger.APPLOGGER.info("Original file name ......... "+ modifiedFileName);
			AppLoger.APPLOGGER.info("Absolute File name ......... "+ files.getAbsolutePath());
			AppLoger.APPLOGGER.info("try File name ......... "+ file.getOriginalFilename().substring(file.getOriginalFilename().lastIndexOf("\\")+1, file.getOriginalFilename().length()));
			newFileName = file.getOriginalFilename().substring(file.getOriginalFilename().lastIndexOf("\\")+1, file.getOriginalFilename().length());
			fileObj.setFileName(newFileName);
			fpData.setFileName(newFileName);
			session.save(fpData);
			file1 = new File("D:\\FTP\\Rightprice\\Ratecard\\"+newFileName);
			
			
			AppLoger.APPLOGGER.info("@adding data to RP_Attachments *+-*+-*+*+*+*+*+*+-*");
			System.out.println("The Original File name is......... ");
			System.out.println(fileObj.getOriginalFileName());
			
			outputStream = new FileOutputStream(file1);
			int read = 0;
			byte[] bytes = new byte[1024];
			try 
			{
				while ((read = ba.read(bytes)) != -1) 
				{
					outputStream.write(bytes, 0, read);
				}
				outputStream.close();
				
				Query updateFileNameAfterInserting = session.createQuery(
						"UPDATE FPManualDealAttachment set fileName=:fileName where dealAttachmentId=:dealAttachmentId and isActive = 1");
				updateFileNameAfterInserting.setParameter("fileName", newFileName);
				updateFileNameAfterInserting.setParameter("dealAttachmentId",fpData.getDealAttachmentId());
				int uploadCount = updateFileNameAfterInserting.executeUpdate();				
			} 
			catch (IOException e1) 
			{	
				e1.printStackTrace();
				throw new Exception(e1.getMessage());
			}
			
			
			
			//Read Excel to save roles 
			/*********************************************************************************************/
			//TO run from Local Code 
				//InputStream stream = new FileInputStream(new File(file1.getAbsolutePath()));
			/*********************************************************************************************/
			
			
			/*********************************************************************************************/
			//To run from Server code
			final String server  = "ftp://10.232.2.20/Rightprice/Ratecard";
			URL url;
			String strFilePath = server + "/" + newFileName;
			url = new URL(strFilePath);
			URLConnection con = url.openConnection();
			AppLoger.APPLOGGER.info("Read Excel : in function uploadManualRateCard: url flow Path :" + server + "/" + strFilePath );
			
			InputStream stream = con.getInputStream();
			/*********************************************************************************************/
			
			Criteria getRCDetails = session.createCriteria(RateCardDetails.class, "rc").add(Restrictions.eq("rcId", fpData.getRpDealVersionId()));
			List<RateCardDetails> rateCardApprovalDetails = getRCDetails.list();
			
			Integer intIsItKpo = rateCardApprovalDetails.get(0).getIsItKpo();
			if(intIsItKpo == 1)
			{
			//Read Role Selection Final T&M sheet & process 
			processExcelData(stream,rateCardApprovalDetails.get(0),session,fpData.getDealAutoTowerId(),countryId);
			
			//session.getTransaction().commit();
			}
			return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body("File Inserted SuccesFully");		
        } 
        catch(Exception e) 
        {
        	//session.getTransaction().rollback();
        	AppLoger.APPLOGGER.info("Error occured : uploadManualRateCard function in RightPriceRepositoryImpl.java");
        	AppLoger.APPLOGGER.info(e.getMessage());
			e.printStackTrace();
        	return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently facing technical issue. Please try again later");
        }
        finally
        {
        	//session.close();
        }
	}
	
	@Override
    public ResponseEntity<Object> saveRateCardDetails(RateCardDetails rateCardDetails) {
           int updatedId = 0;
           String Status=rateCardDetails.getStatusIndicator();
           Session session = this.sessionFactory.getCurrentSession();
           
           RateCardTest rcDetail=null;
           Criteria crit = session.createCriteria(RateCardTest.class, "rc").add(Restrictions.eq("rcId", rateCardDetails.getRcId()));
			List<RateCardTest> rateCardAfterProc = crit.list();
			for (Object objects : rateCardAfterProc) {
				 rcDetail = (RateCardTest)objects;
				
			}
           
           
           try {
        	   String syntelLanId= getSyntelId(this.auditTrails.getCurrentUser());
        	   if(rateCardDetails.getExpectedRCEndDate() == null){
        		   Query query = session.createQuery("update RateCardDetails set currentApprovalStatus = :currentApprovalStatus,statusIndicator = :statusIndicator,rccomments = :rccomments ,updatedBy=:updatedBy,updatedOn=:updatedOn where rcId = :rcId");
        		   query.setParameter("currentApprovalStatus", 5);
        		   query.setParameter("statusIndicator","DEACTIVATED");
    				if(syntelLanId.isEmpty() || syntelLanId==null)
    				{
    					query.setParameter("rccomments", "[ "+this.auditTrails.getCurrentUser() +" ] : "+ rateCardDetails.getRccomments());
    				}
    				else
    				{
        		   query.setParameter("rccomments", "[ "+syntelLanId +" ] : "+ rateCardDetails.getRccomments());
    				}
        		   query.setParameter("rcId", rateCardDetails.getRcId());
    				if(syntelLanId.isEmpty() || syntelLanId==null)
    				{
    					 query.setParameter("updatedBy", this.auditTrails.getCurrentUser());
    				}
    				else
    				{
        		   query.setParameter("updatedBy", syntelLanId);
    				}
        		   query.setParameter("updatedOn", this.auditTrails.getCurrentTimeStamp());
        		   updatedId= query.executeUpdate();
        		   if(updatedId>0){
        		
					sendMails(3,rateCardDetails.getRcId(),session,rateCardDetails.getRccomments(),Status,rateCardDetails,rcDetail);
        		   }
        	   }
        	   else{
        		   Query query = session.createQuery("update RateCardDetails set expectedRCEndDate = :expectedRCEndDate,rccomments = :rccomments,updatedBy=:updatedBy,updatedOn=:updatedOn where rcId = :rcId");
        		   query.setParameter("expectedRCEndDate", rateCardDetails.getExpectedRCEndDate());
        		   if(syntelLanId.isEmpty() || syntelLanId==null)
   				{
   					query.setParameter("rccomments", "[ "+this.auditTrails.getCurrentUser() +" ] : "+ rateCardDetails.getRccomments());
   				}
   				else
   				{
        		   query.setParameter("rccomments", "[ "+syntelLanId +" ] : "+ rateCardDetails.getRccomments());
   				}
        		   query.setParameter("rcId", rateCardDetails.getRcId());
        		   if(syntelLanId.isEmpty() || syntelLanId==null)
   				{
        			   query.setParameter("updatedBy", this.auditTrails.getCurrentUser());
   				}
   				else
   				{
        		   query.setParameter("updatedBy", syntelLanId);
   				}
        		   query.setParameter("updatedOn", this.auditTrails.getCurrentTimeStamp());
        		   updatedId = query.executeUpdate();
        		   if(updatedId>0){
        			   sendMails(4,rateCardDetails.getRcId(),session,rateCardDetails.getRccomments(),Status,rateCardDetails,rcDetail);
        		   }
        	   }
        	   
        	   if(updatedId>0){
        		   return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body("Rate Card details updated successfully.");
        	   }else{
        		   return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently We are facing technical issues, please try again later.");
        	   }
           } catch(Exception e) {
        	   return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently We are facing technical issues, please try again later."+e.getMessage());
           } finally {
        	   //session.close();
           }
           
    }

