	@Override
	public ResponseEntity<Object> getrateCardId() {
		Session session = this.sessionFactory.getCurrentSession();
		String getData="select t1.RC_ID, t1.Customer_Vertical_Map_Id,t1.RC_Name,t1.RC_Start_Date,t1.RC_End_Date,t1.IS_ACTIVE,t1.CREATED_BY,t1.CREATED_ON,t1.UPDATED_BY,t1.UPDATED_ON,t1.RC_Comments,"
                +" t1.Expected_RC_End_Date,t1.Current_Approval_Status,t3.Customer_Name from synprod.RP_Rate_Card_Details  t1"
                +" JOIN synprod.MST_RP_Customer_Vertical_Mapping t2 on t2.Customer_Vertical_Map_Id = t1.Customer_Vertical_Map_Id"
                +" JOIN synprod.MST_RP_Customer t3 on t3.Customer_Id = t2.Customer_id"
                +" where Current_Approval_Status = 3 OR Current_Approval_Status = 6";
		Query quer = session.createSQLQuery(getData).addEntity(VirewMasterRateCard.class);
		List<VirewMasterRateCard> subpracticeList = quer.list();
		for (Object object : subpracticeList) {
			VirewMasterRateCard subprac = (VirewMasterRateCard) object;
		}
		if (!subpracticeList.isEmpty()) {
			//session.close();
			return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(subpracticeList);
		} else {
			//session.close();
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body(subpracticeList);
		}
	}

