@Override
public ResponseEntity<Object> updateRateCardStatus(int rcId) {
	// TODO Auto-generated method stub
	Session session = this.sessionFactory.getCurrentSession();
	try {
		int approvalStatus = 7;
		String statusIndicator = "GFT";
		String comment="Send For Approval";
		RateCardDetails con= new RateCardDetails();
		con.setStatusIndicator(statusIndicator);
		con.setUserType("Delivery");
		AppLoger.APPLOGGER.info("Inside the Rate Card Details Update");
		Query updateManualRCId = session.createQuery(
				"UPDATE RateCardDetails set currentApprovalStatus=:approvalStatus,statusIndicator=:statusIndicator where rcId=:rcId and isActive = 1");
		updateManualRCId.setParameter("approvalStatus", approvalStatus);
		updateManualRCId.setParameter("statusIndicator", statusIndicator);
		updateManualRCId.setParameter("rcId",rcId);
		int uploadCount = updateManualRCId.executeUpdate();
		
		RateCardTest rcDetail=null;
        Criteria crit = session.createCriteria(RateCardTest.class, "rc").add(Restrictions.eq("rcId", rcId));
			List<RateCardTest> rateCardAfterProc = crit.list();
			for (Object objects : rateCardAfterProc) {
				 rcDetail = (RateCardTest)objects;
				 rcDetail.setUserType("Delivery");
			}
		sendMails(11, rcId,session,comment,statusIndicator,con,rcDetail);
		
		if(uploadCount > 0 ) {
			return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body("File Inserted SuccesFully");
		} else 
		{
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently Facing Technical Issue.");
		}
	} catch (Exception e) {
		return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently Facing Technical Issue."+e.getMessage());
	} finally {
		//session.close();
	}
	}

