	@Override
	public ResponseEntity<Object> updateCustomer(Customer customer) {
		int updateCustomer = 0;
		Session session = this.sessionFactory.getCurrentSession();
		
		Query query = session.createQuery("UPDATE Customer set onsiteWorkHours=:onsiteWorkHours,offshoreWorkHours=:offshoreWorkHours,"
				+ "cpcCharges=:cpcCharges,ipcCharges=:ipcCharges,volumeDiscount=:volumeDiscount,cpcChargesFP=:cpcChargesFP "
				+ "where customerName=:customerName");
		
		query.setParameter("customerName", customer.getCustomerName());
		query.setParameter("onsiteWorkHours", customer.getOnsiteWorkHours());
		query.setParameter("offshoreWorkHours", customer.getOffshoreWorkHours());
		query.setParameter("cpcCharges", customer.getCpcCharges());
		query.setParameter("cpcChargesFP", customer.getCpcChargesFP());
		query.setParameter("ipcCharges", customer.getIpcCharges());
		query.setParameter("volumeDiscount", customer.getVolumeDiscount());
		
		
		
		updateCustomer = query.executeUpdate();
		if (updateCustomer > 0) {
			//session.close();
			return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(updateCustomer);
		} else {
			//session.close();
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body(updateCustomer);
		}
	}
	
	
