	@Override
	public ResponseEntity<Object> getDealApproverInfo(int rpVrsId) {
		AppLoger.APPLOGGER.info("RightPriceRepositoryImpl -- getDealApproverDesignation");
		Session getDealDetails = this.sessionFactory.getCurrentSession();
		Double tempTcv;
		Double tempMargin;
		Double tempOffshoreAllocation;

		int tempIsManual = 0;
		Session session = this.sessionFactory.getCurrentSession();
		try {
			Criteria c = getDealDetails.createCriteria(Deal.class, "deal").add(Restrictions.eq("rpDealVersionId", rpVrsId));
			List rcDetails = c.list();
			for (Object obj : rcDetails) {
				Deal dealData = (Deal) obj;
				tempTcv = (double) dealData.getDealTcv();
				tempMargin = dealData.getGmPercentage();
				tempOffshoreAllocation = dealData.getOffShoreHours();
				
				if (dealData.getDealTypeId() == 1) {
					tempIsManual = 1;
				} else {
					tempIsManual = 0;
				}
				
				Query storeProcQuery = getDealDetails
						.createSQLQuery(
								"{CALL synprod.RP_SET_Approval_Levels_for_deal(:rpVrsId,:inputType)}")
						.setParameter("rpVrsId", rpVrsId).setParameter("inputType", "TMD");
				
				/*"{CALL synprod.RP_SET_Approval_Levels_for_deal(:rpVrsId,:inputType,:tcv,:margin,:offshoreAllocation,:campusHires)}")
			.setParameter("rpVrsId", rpVrsId).setParameter("inputType", "TMD").setParameter("tcv", tempTcv)
			.setParameter("margin", tempMargin).setParameter("offshoreAllocation", tempOffshoreAllocation)
			.setParameter("campusHires", 10);*/
				// .setParameter("isManual", tempIsManual);
				
				List result = storeProcQuery.list();
				AppLoger.APPLOGGER.info("RESULT");
				AppLoger.APPLOGGER.info(result);
			}
			
			
			Criteria crit = session.createCriteria(Deal.class, "deal").add(Restrictions.eq("rpDealVersionId", rpVrsId));
			crit.createCriteria("level1ApprovalId", "level1ApprovalId", org.hibernate.sql.JoinType.LEFT_OUTER_JOIN)
			.add(Restrictions.or(Restrictions.ilike("codeType", "%User_Role%"), Restrictions.isNull("codeType")));
			crit.createCriteria("level2ApproverId", "level2ApproverId", org.hibernate.sql.JoinType.LEFT_OUTER_JOIN)
			.add(Restrictions.or(Restrictions.ilike("codeType", "%User_Role%"), Restrictions.isNull("codeType")));
			crit.createCriteria("level3ApproverId", "level3ApproverId", org.hibernate.sql.JoinType.LEFT_OUTER_JOIN)
			.add(Restrictions.or(Restrictions.ilike("codeType", "%User_Role%"), Restrictions.isNull("codeType")));
			crit.createCriteria("level4ApproverId", "level4ApproverId", org.hibernate.sql.JoinType.LEFT_OUTER_JOIN)
			.add(Restrictions.or(Restrictions.ilike("codeType", "%User_Role%"), Restrictions.isNull("codeType")));
			crit.createCriteria("level5ApproverId", "level5ApproverId", org.hibernate.sql.JoinType.LEFT_OUTER_JOIN)
			.add(Restrictions.or(Restrictions.ilike("codeType", "%User_Role%"), Restrictions.isNull("codeType")));
			crit.createCriteria("level6ApproverId", "level6ApproverId", org.hibernate.sql.JoinType.LEFT_OUTER_JOIN)
			.add(Restrictions.or(Restrictions.ilike("codeType", "%User_Role%"), Restrictions.isNull("codeType")));
			crit.createCriteria("level7ApproverId", "level7ApproverId", org.hibernate.sql.JoinType.LEFT_OUTER_JOIN)
			.add(Restrictions.or(Restrictions.ilike("codeType", "%User_Role%"), Restrictions.isNull("codeType")));
			List approverDesigList = crit.list();
			for (Object object : approverDesigList) {
				Deal approverDesignation = (Deal) object;
				AppLoger.APPLOGGER.info("DealDetails is   " + approverDesignation.getLevel2ApproverRoleId() + "________"
						+ approverDesignation.getLevel3ApproverRoleId());
			}
			if (!approverDesigList.isEmpty()) {
				
				return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(approverDesigList);
			} else {
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body(approverDesigList);
			}
		} catch (Exception e) {
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("approverDesigList"+e.getMessage());
		} finally {
			//getDealDetails.close();
			//session.close();
		}
	}
	
