	private int getOldProjectId(int dealID) {
		System.out.println("The Deal Id is....... "+dealID);
		Integer projectId = 0;
		String getprojectId = "SELECT tim_project.project_id as projectId,tim_project.descr FROM synprod.tim_project "
				+ "WHERE tim_project.deal_id=?";
		try {
			AppLoger.APPLOGGER.info("Query : " + getprojectId);
			SqlRowSet set = mssqlTemplate.queryForRowSet(getprojectId,
					new Object[] { dealID});
			AppLoger.APPLOGGER.info("Query Status: " + !set.wasNull());
			while (set.next()) {
				projectId = set.getInt("projectId");
				AppLoger.APPLOGGER.info(" projectId :::::::::::::::::::::::: " + projectId );
			}
		} catch (Exception e) {
			e.printStackTrace();
		}
		return projectId;
	}

