	@Override
	public ResponseEntity<Object> getFpDealRateCard(int dealTowerId,int dealVersionId) {
		Session session = this.sessionFactory.getCurrentSession();
 		String get_entity = "SELECT rcd.RC_Id as RC_Id,rcd.RC_Name as RC_Name,rcd.Is_Atos as Is_Atos FROM synprod.RP_FP_Deal_RateCards rpd, "
				+ " synprod.RP_Rate_Card_Details rcd  WHERE rcd.RC_Id = rpd.Deal_RC_Id and "
				+ " rpd.Deal_Tower_ID="+dealTowerId+" and  rpd.RP_Deal_Version_Id="+dealVersionId+" and rpd.Is_Active=1 and rcd.RC_Id >=8000  ";
		Query quer = session.createSQLQuery(get_entity).addEntity(RPRateCardDetails.class);
		List entityList = quer.list();
		AppLoger.APPLOGGER.info("Entity List :");
		for (Object object : entityList) {
			RPRateCardDetails roleSelection = (RPRateCardDetails) object;
			AppLoger.APPLOGGER.info("ID  : " + roleSelection.getRcId());
			AppLoger.APPLOGGER.info("Name  : " + roleSelection.getRcName());
			AppLoger.APPLOGGER.info("IsAtos  : " + roleSelection.getIsAtos());
		}
		if (!entityList.isEmpty()) {
			//session.close();
			return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(entityList);
		} else {
			//session.close();
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body(entityList);
		}
	}
	
	
