 	public String getCurrencyname(int currencyId){
		String currencyName="";
		switch (currencyId) {
  		case 1 : 
  			currencyName = "USD";
  			break;
  		case 2 : 
  			currencyName = "INR";
  			break;
  		case 3 : 
  			currencyName = "CAD";
  			break;
  		case 4 : 
  			currencyName = "EUR";
  			break;
  		case 5 : 
  			currencyName = "GBP";
  			break;
  		case 6 : 
  			currencyName = "AUD";
  			break;
		case 7 : 
			currencyName = "Common";
			break;
		default : 
  			break;
		}
		return currencyName;
		
	}
 	
