	private boolean saveManualDealRPSummary(String strFilePath, FPManualDealAttachment fpData, Session session,Deal objDeal) throws IOException 
	{
		String syntelLanId= getSyntelId(this.auditTrails.getCurrentUser());
		AppLoger.APPLOGGER.info("Read Excel : in function saveManualDealRPSummary ");
		AppLoger.APPLOGGER.info("Read Excel : in function saveManualDealRPSummary: File Path :" + strFilePath );
		RPDealManualSTG objRPDealManualSTG = new RPDealManualSTG();

		/*********************************************************************************************/
		//TO run from Local Code 
//		InputStream stream = new FileInputStream(new File(strFilePath));
		/*********************************************************************************************/
		
		/*********************************************************************************************/
		//To run from Server code
		final String server  = "ftp://10.232.2.20/Rightprice/Ratecard";
		URL url;
		url = new URL(strFilePath);
		URLConnection con = url.openConnection();
		AppLoger.APPLOGGER.info("Read Excel : in function saveManualDealRPSummary: url flow Path :" + server + "/" + strFilePath );
		
		InputStream stream = con.getInputStream(); 
		/*********************************************************************************************/
		
		XSSFWorkbook workbook = new XSSFWorkbook(stream);
		
		AppLoger.APPLOGGER.info("Read Excel : Summary data in function saveManualDealRPSummary ");
		for(int i=0; i<workbook.getNumberOfSheets(); i++)
		{
			XSSFSheet sheet = workbook.getSheetAt(i);
			System.out.println("sheet Name: \t" + sheet.getSheetName());
			
			// if found sheet name "Summary"
			if(sheet.getSheetName().trim().equalsIgnoreCase("Summary"))
			{
				for (int j = 3; j <= sheet.getLastRowNum(); j++) 
				{
					int columnCount = sheet.getRow(j).getLastCellNum();
					System.out.println("Column Count is............" + columnCount);
					XSSFRow row = sheet.getRow(j);
					
					if (row.getCell(2) != null)//&& row.getCell(2).getStringCellValue().isEmpty() == false)
					{
						switch(j)
						{
						case 3:									
							Double dblOnsitePercentage = row.getCell(2).getNumericCellValue() * 100;
							objRPDealManualSTG.setOnsitePercentage(new BigDecimal(dblOnsitePercentage).setScale(4, RoundingMode.HALF_UP).doubleValue());
							break;
						case 4:
							Double dblOffshorePercentage = row.getCell(2).getNumericCellValue() * 100;
							objRPDealManualSTG.setOffshorePercentage(new BigDecimal(dblOffshorePercentage).setScale(4, RoundingMode.HALF_UP).doubleValue());
							break;
						case 5:			
							row.getCell(2).setCellType(CellType.NUMERIC);
							BigDecimal dblRevenue =  new BigDecimal(row.getCell(2).getNumericCellValue());
							BigDecimal roundOffdblRevenue = dblRevenue.setScale(2, BigDecimal.ROUND_HALF_EVEN);							
							objRPDealManualSTG.setRevenue(roundOffdblRevenue);
							BigDecimal dblSFTCV =  BigDecimal.valueOf(objDeal.getDealTcv());
							Double revPerCheck=(roundOffdblRevenue.divide(dblSFTCV,4,RoundingMode.CEILING)).doubleValue();
							
							if(!((revPerCheck >= 0.995) && (revPerCheck <= 1.005)))
	  	    				{
								return false;
	  	    				}
							
							break;
						case 6:
							row.getCell(2).setCellType(CellType.NUMERIC);
							BigDecimal dbldirectCost = new BigDecimal(row.getCell(2).getNumericCellValue());							
							BigDecimal roundOff = dbldirectCost.setScale(4, BigDecimal.ROUND_HALF_EVEN);							
							objRPDealManualSTG.setDirectCost(roundOff);
							break;
						case 7:
							Double dblgrossMarginPercentage = row.getCell(2).getNumericCellValue();
							objRPDealManualSTG.setGrossMarginPercentage(new BigDecimal(dblgrossMarginPercentage).setScale(4, RoundingMode.HALF_UP).doubleValue());
							break;
						case 8:			
							Double dblProjectSpecSGAIncludAgileCost = row.getCell(2).getNumericCellValue();
							objRPDealManualSTG.setProjectSpecificSGAIncludingAgileCost(new BigDecimal(dblProjectSpecSGAIncludAgileCost).setScale(2, RoundingMode.HALF_UP).doubleValue());
							break;
						case 9:
							Double dbloMPercentage = row.getCell(2).getNumericCellValue();
							objRPDealManualSTG.setoMPercentage(new BigDecimal(dbloMPercentage).setScale(4, RoundingMode.HALF_UP).doubleValue());
							break;
						case 10:
							Double dblvolDiscountPercent = row.getCell(2).getNumericCellValue() * 100;
							objRPDealManualSTG.setVolumeDiscountPercentage(new BigDecimal(dblvolDiscountPercent).setScale(4, RoundingMode.HALF_UP).doubleValue());
							break;
						case 11:
							Double dblpenaltyPercentage = row.getCell(2).getNumericCellValue() * 100;
							objRPDealManualSTG.setPenaltyPercentage(new BigDecimal(dblpenaltyPercentage).setScale(4, RoundingMode.HALF_UP).doubleValue());
							break;
						case 12:
							Double dbloMPerAfterVolDisc = row.getCell(2).getNumericCellValue();
							objRPDealManualSTG.setoMPercentageAfterVolumeDiscount(new BigDecimal(dbloMPerAfterVolDisc).setScale(4, RoundingMode.HALF_UP).doubleValue());
							break;
						case 13:								
							Double dblProjectMargin  = row.getCell(2).getNumericCellValue();	
							//new BigDecimal(row.getCell(2).getNumericCellValue());			
							//BigDecimal roundOffdblProjectMargin = dblProjectMargin.setScale(4, BigDecimal.ROUND_HALF_EVEN);
							objRPDealManualSTG.setProjectMargin(new BigDecimal(dblProjectMargin).setScale(4, RoundingMode.HALF_UP).doubleValue());
							break;				
							case 14:
							Double dblpminclrisk = row.getCell(2).getNumericCellValue();	
							objRPDealManualSTG.setPminclrisk(new BigDecimal(dblpminclrisk).setScale(4, RoundingMode.HALF_UP).doubleValue());
							break;				
							case 15:	
							Double dblpminclRiskVD = row.getCell(2).getNumericCellValue();
							objRPDealManualSTG.setPminclRiskVD(new BigDecimal(dblpminclRiskVD).setScale(4, RoundingMode.CEILING).doubleValue());
							break;
							
							
						default :
							break;
							
						} // switch case end
					}
					
				}//for loop
				objRPDealManualSTG.setRPDealVersionId(fpData.getRpDealVersionId());
				objRPDealManualSTG.setTowerId(fpData.getDealAutoTowerId());
				if(syntelLanId.isEmpty() || syntelLanId==null)
				{
					objRPDealManualSTG.setCreatedBy(this.auditTrails.getCurrentUser());
					objRPDealManualSTG.setCreatedDate(this.auditTrails.getCurrentTimeStamp());
					objRPDealManualSTG.setUpdatedBy(this.auditTrails.getCurrentUser());
					objRPDealManualSTG.setUpdatedDate(this.auditTrails.getCurrentTimeStamp());
				}
				else
				{
					objRPDealManualSTG.setCreatedBy(syntelLanId);
					objRPDealManualSTG.setCreatedDate(this.auditTrails.getCurrentTimeStamp());
					objRPDealManualSTG.setUpdatedBy(syntelLanId);
					objRPDealManualSTG.setUpdatedDate(this.auditTrails.getCurrentTimeStamp());
				}
				//workbook.close();
				stream.close();

				AppLoger.APPLOGGER.info("Read Excel : Summary data in function saveManualDealRPSummary: Calling savemanualDeal function");
				saveManualDeal(session, objRPDealManualSTG);				
			}
		}
		 return true;
	}
	
	
