	@Override
	public ResponseEntity<Object> getFpDealCostInputsDetails(int towerId, int costType,int rpdealVersionId) {
		Session session = sessionFactory.getCurrentSession();
		try {
			session.beginTransaction();
			Criteria crit = session.createCriteria(DealIndirectCostInputs.class,"dealIndirectCostInputs").add(Restrictions.eq("indirectCostType", costType))
				.add(Restrictions.eq("dealTowerId", towerId)).add(Restrictions.eq("rpDetalVersionId", rpdealVersionId));
		crit.createAlias("staffingDetailsHeader", "staffingDetailsHeader");
		crit.createAlias("inDirectCostmaster", "inDirectCostmaster");
		List<DealIndirectCostInputs> costInputData = crit.list();
		session.getTransaction().commit();
		AppLoger.APPLOGGER.info("updated");
		//session.close();
		return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(costInputData);
		}
		catch(Exception e)
		{
			session.getTransaction().rollback();
			//session.close();
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("No Data Found.");
		}
		
	}

