	@Override
	public ResponseEntity<Object> updateFPApproverDetails(FpDeal fpData) {
		int updateId = 0;
		Session session = this.sessionFactory.getCurrentSession();
		Session sessionup = this.sessionFactory.getCurrentSession();
		
		Criteria check = session.createCriteria(FpDeal.class, "fpdeal").add(Restrictions.eq("rpDealVersionId",fpData.getRpDealVersionId() ));
		List<FpDeal> fpdealsDetails = check.list();
		String crmId=fpdealsDetails.get(0).getCrmDealId();
		String Status="";
		//String Status1="RiskManagers";
		Integer versionId=fpdealsDetails.get(0).getRpDealVersionId();
		
		try {
			
			Query query = session.createQuery(
					"update FpDeal set currentApprovalStatus = :currentApprovalStatus, currentApproverId = :currentApproverId,currentApprovalLevel = :currentApprovalLevel, updatedBy = :updatedBy, updatedDate = :updatedDate,"
					+ " updateAtosEmailId =:updateAtosEmailId, updateEmployeeName =:updateEmployeeName,  approverComments= :approverComments, statusIndicator= :statusIndicator where rpDealVersionId = :rpDealVersionId");
			query.setParameter("currentApprovalStatus", fpData.getCurrentApprovalStatus());
			query.setParameter("currentApproverId", fpData.getCurrentApproverId());
			query.setParameter("currentApprovalLevel", fpData.getCurrentApprovalLevel());
			query.setParameter("updatedBy", fpData.getUpdatedBy());
			query.setParameter("updatedDate", fpData.getUpdatedDate());
			query.setParameter("updateAtosEmailId", fpData.getUpdateAtosEmailId());
			query.setParameter("updateEmployeeName", fpData.getUpdateEmployeeName());
			query.setParameter("approverComments", fpData.getApproverComments());
			query.setParameter("statusIndicator", fpData.getStatusIndicator());
			query.setParameter("rpDealVersionId", fpData.getRpDealVersionId());
			updateId = query.executeUpdate();
			AppLoger.APPLOGGER.info("data for rc updated----------------------------------------" + updateId);
			String updatedStaus=fpData.getStatusIndicator();
			
			Criteria critup = sessionup.createCriteria(FpDeal.class,"FpDeal").add(Restrictions.eq("crmDealId",fpData.getCrmDealId()))
					.add(Restrictions.eq("isActive", 1)).add(Restrictions.not(Restrictions.eq("currentApprovalStatus", 2)));	
			List<FpDeal> fpdealDetails = critup.list();
			for(FpDeal fpupdate : fpdealDetails) {
				Query  deactivateApproverVersion = session.createQuery("update FpDeal set currentApprovalStatus = 5 "
							+ "where rpDealVersionId= " + fpupdate.getRpDealVersionId());
					int updateWhatIfDetailsQueryCount = deactivateApproverVersion.executeUpdate();
			}
			
			if(updateId>0)
			{
				String syntelLanId= getSyntelId(this.auditTrails.getCurrentUser());
					if(syntelLanId.isEmpty()||syntelLanId==null)
					{
						sendMailFixedPrice(10,versionId,session,this.auditTrails.getCurrentUser(),crmId,fpData.getApproverComments(),Status,updatedStaus);	
					}else
					{
						sendMailFixedPrice(10,versionId,session,syntelLanId,crmId,fpData.getApproverComments(),Status,updatedStaus);
					}
				
			}
			
			//session.close();
			//sessionup.close();
			return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body("Successfully Sent For Approval.");
		} catch(Exception e) {
			AppLoger.APPLOGGER.info("Exception in Update Approval for Deal "+e);
			//session.close();
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN)
					.body("Currently We are facing technical issues, please try again later.");
		}
	}

