	@Override
	public ResponseEntity<Object> deleteDealVersion(int dltDealVersionId,String userName) {
		int deleteDealVersion = 0;
		String Authentication="Failed";
		Session session = this.sessionFactory.getCurrentSession();
		
		Query checkAuth = session.createQuery("from AccessControl WHERE lanId=? and isActive=?");
		checkAuth.setParameter(0, userName);
		checkAuth.setParameter(1, 1);
		List<AccessControl> customerAccess = checkAuth.list();
		
	    Query dealData = session.createQuery("from Deal WHERE rpDealVersionId=? and isActive=? ");
	    dealData.setParameter(0, dltDealVersionId);
	    dealData.setParameter(1, 1);
		List<Deal> lstdealData= dealData.list();
		
		for(int i=0;i<customerAccess.size();i++){
			if(customerAccess.get(i).getCustomerId().equals(lstdealData.get(0).getCustomerId() )){
				Authentication = "Success";
			}
		}
		if(Authentication.equals("Success")){
		Query query = session.createQuery("UPDATE MyDashboardDeal set isActive = :isActive , updatedDate= :updatedon , updatedBy= :updatedBy where rpDealVersionId = :rpDealVersionId");
		query.setParameter("isActive", 0);
		query.setParameter("updatedon", auditTrails.getCurrentTimeStamp());
		query.setParameter("updatedBy", auditTrails.getCurrentUser());
		query.setParameter("rpDealVersionId", dltDealVersionId);
		deleteDealVersion = query.executeUpdate();
		}
		if (deleteDealVersion > 0) {
			//session.close();
			return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(deleteDealVersion);
		} else {
			//session.close();
			return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body(deleteDealVersion);
		}

	}

