	private void saveSkillForcastStaffDateRangeData(Session session, ResourceForecast resourceForecast, SkillforecastStaffingDateRange skillforecastStaffingDateRange) 
	{
		//Insert data into skillforecastStaffingDateRange
		//SkillforecastStaffingDateRange staffingData=new SkillforecastStaffingDateRange();
		skillforecastStaffingDateRange.setId(resourceForecast.getId());
		skillforecastStaffingDateRange.setOpportunityId(resourceForecast.getDealId());
		skillforecastStaffingDateRange.setStartDate(resourceForecast.getStartDate());
		skillforecastStaffingDateRange.setEndDate(resourceForecast.getEndDate());
		skillforecastStaffingDateRange.setRole(resourceForecast.getSyntelRoleName());
		skillforecastStaffingDateRange.setCatogery(resourceForecast.getLocation());
		skillforecastStaffingDateRange.setBand(resourceForecast.getSyntelXOBandGrade());
		skillforecastStaffingDateRange.setQuantity(resourceForecast.getNoOfResource());
		skillforecastStaffingDateRange.setSkillsName(resourceForecast.getSkillElement());
		
		Criteria crits = session.createCriteria(ResourceForecastLobData.class, "forecastLob").add(Restrictions.eq("dealId",resourceForecast.getDealId()));
		List <ResourceForecastLobData> lobdata = crits.list();
		skillforecastStaffingDateRange.setLob((lobdata.size()> 0 && lobdata.get(0).getLob()!= null)? lobdata.get(0).getLob():null);
		
		skillforecastStaffingDateRange.setExperience(0);
		skillforecastStaffingDateRange.setSkillID(resourceForecast.getSkillID());
		skillforecastStaffingDateRange.setSkillElementId(resourceForecast.getSkillElementId());
		skillforecastStaffingDateRange.setxOKnowledgeID(resourceForecast.getSyntelXOKnowledgeID());
		skillforecastStaffingDateRange.setXoGrade(resourceForecast.getSyntelXOBandGrade());
		skillforecastStaffingDateRange.setXoBand(resourceForecast.getSyntelXOBandGrade());
		skillforecastStaffingDateRange.setKnowledgeSkillName(resourceForecast.getSkill());
		skillforecastStaffingDateRange.setxOKnowledgeName(resourceForecast.getSyntelXOKnowledge());
		skillforecastStaffingDateRange.setXoSkillName(resourceForecast.getSkill());
		skillforecastStaffingDateRange.setMigrationStatus("Y");
		skillforecastStaffingDateRange.setRunDate(this.auditTrails.getCurrentTimeStamp());
		skillforecastStaffingDateRange.setIsActive(resourceForecast.getIsActive());
		skillforecastStaffingDateRange.setCreatedBy(resourceForecast.getCreatedBy());
		skillforecastStaffingDateRange.setCreatedOn(this.auditTrails.getCurrentTimeStamp());
		skillforecastStaffingDateRange.setUpdatedBy(resourceForecast.getUpdatedBy());
		skillforecastStaffingDateRange.setUpdatedOn(this.auditTrails.getCurrentTimeStamp());

		session.save(skillforecastStaffingDateRange);
	}
	
