	    private Map<Integer, List<Long>>  getDealEfforts(List DealList,Session session) 
	    {
	    	Map<Integer, List<Long>> map = new HashMap<Integer, List<Long>>();
	    	
			List<Long> localvalue = new ArrayList<Long>();		
			List<Long> longTermvalue = new ArrayList<Long>();		
			List<Long> shortTermvalue = new ArrayList<Long>();
			List<Long> offShorevalue = new ArrayList<Long>();
			
			List<Long> deputedvalue = new ArrayList<Long>();
			List<Long> onsiteTotal = new ArrayList<Long>();
			List<Long>offshoreTotal = new ArrayList<Long>();
			
			List lstLocalEfforts = null;		
			List lstLongTerms = null;		
			List lstShortTerms = null;
			List lstOffShore = null;
			
			Double deputed=0.0,domestic=0.0,shortTerm=0.0,longTerm=0.0,offshoreTerm=0.0,onsite=0.0,offshore=0.0;
			long domestics=0,longTerms=0,shortTerms=0,offshoreTerms=0,deputeds=0,onsites=0,offshores=0;
			
		 	for(int i=0;i<DealList.size();i++)
		 	{
		 		
		 		Query qryGetlocalEfforts= session.createQuery("SELECT effortsTotal from  FPDealWhatIfEffort where Is_Active=:Is_Active "
		 				+ "AND RP_Deal_Version_Id =:RPDealVersionId and location_type_ID =:location_type_ID");
		 		qryGetlocalEfforts.setParameter("Is_Active", 1);
		 		qryGetlocalEfforts.setParameter("RPDealVersionId", DealList.get(i));
		 		qryGetlocalEfforts.setParameter("location_type_ID", 1);
		 		lstLocalEfforts = qryGetlocalEfforts.list();
		 		
		 		if(lstLocalEfforts.size()!=0){
		 			domestic=(Double) lstLocalEfforts.get(0);
		 			domestics=(Math.round(domestic));
		 			
			 		localvalue.add(domestics);
		 		}
		 		else{
		 			localvalue.add((long) 0);
		 		}
		 		lstLocalEfforts = null;

		 		
		 		Query qryLTDepEfforts= session.createQuery("SELECT effortsTotal from  FPDealWhatIfEffort where Is_Active=:Is_Active "
		 				+ "AND RP_Deal_Version_Id =:RPDealVersionId and location_type_ID =:location_type_ID");
		 		qryLTDepEfforts.setParameter("Is_Active", 1);
		 		qryLTDepEfforts.setParameter("RPDealVersionId", DealList.get(i));
		 		qryLTDepEfforts.setParameter("location_type_ID", 2);
		 		lstLongTerms = qryLTDepEfforts.list();	
		 		
		 		if(lstLongTerms.size()!=0){
		 			longTerm=(Double) lstLongTerms.get(0);
		 			longTerms=(Math.round(longTerm));
					longTermvalue.add(longTerms);
		 		}
		 		else{
		 			longTermvalue.add((long) 0);
		 		}
		 		lstLongTerms = null;
		 		
		 		
		 		Query qrySTdepEfforts= session.createQuery("SELECT effortsTotal from  FPDealWhatIfEffort where Is_Active=:Is_Active "
		 				+ "AND RP_Deal_Version_Id =:RPDealVersionId and location_type_ID =:location_type_ID");
		 		qrySTdepEfforts.setParameter("Is_Active", 1);
		 		qrySTdepEfforts.setParameter("RPDealVersionId", DealList.get(i));
		 		qrySTdepEfforts.setParameter("location_type_ID", 3);
		 		lstShortTerms = qrySTdepEfforts.list();	
		 		
		 		if(lstShortTerms.size()!=0){
		 			shortTerm=(Double) lstShortTerms.get(0);
		 			shortTerms=(Math.round(shortTerm));
			 		shortTermvalue.add(shortTerms);
		 		}
		 		else{
		 			shortTermvalue.add((long) 0);
		 		}
		 		lstShortTerms = null;
		 		
		 		Query qryOnsiteEfforts= session.createQuery("SELECT effortsTotal from  FPDealWhatIfEffort where Is_Active=:Is_Active "
		 				+ "AND RP_Deal_Version_Id =:RPDealVersionId and location_type_ID =:location_type_ID");
		 		qryOnsiteEfforts.setParameter("Is_Active", 1);
		 		qryOnsiteEfforts.setParameter("RPDealVersionId", DealList.get(i));
		 		qryOnsiteEfforts.setParameter("location_type_ID", 5);
		 		lstOffShore = qryOnsiteEfforts.list();	
		 		
		 		if(lstOffShore.size()!=0){
		 			offshoreTerm=(Double) lstOffShore.get(0);
		 			offshoreTerms=(Math.round(offshoreTerm));
			 		offShorevalue.add(offshoreTerms);
		 		}
		 		else{
		 			offShorevalue.add((long) 0);
		 		}
		 		lstOffShore = null;
		 		
				deputeds=longTerms+shortTerms;	
				deputedvalue.add(deputeds);
				onsites=domestics+longTerms+shortTerms;
				onsiteTotal.add(onsites);
				offshores=onsites+offshoreTerms;
				offshoreTotal.add(offshores);
				
		 	}

			map.put(1,offshoreTotal);
			map.put(2,localvalue);
			map.put(3, deputedvalue);
			map.put(4, offShorevalue);
		 	
			return map.isEmpty() ? null : map;  
		}
	    
	    
	    @Override
		public ResponseEntity<Object> getOldDealDetails(int customerId,String startDate) {
			Session session = sessionFactory.getCurrentSession();
			try {
				session.beginTransaction();
				AppLoger.APPLOGGER.info("cuurent Time ");
				//Date startDate = Calendar.getInstance().getTime();
				SimpleDateFormat formatter = new SimpleDateFormat("yyyy-MM-dd HH:mm:sss");
				//String todayString = formatter.format(startDate);
				String newStartDate = startDate;
				AppLoger.APPLOGGER.info(newStartDate);
				Calendar c = Calendar.getInstance();
				  c.setTime(formatter.parse(newStartDate));
				  c.add(Calendar.DATE, -90); 
				  String newDate = formatter.format(c.getTime()); 
				  AppLoger.APPLOGGER.info("Updated date 90 days from today");
				  AppLoger.APPLOGGER.info(newDate);
				Criteria crit = session.createCriteria(RpOldDeal.class,"RpOldDeal")
					.add(Restrictions.eq("customerId", customerId)).add(Restrictions.gt("dealEndDate", newDate))
					.add(Restrictions.eq("isActive", 1))
					.addOrder(Order.asc("crmDealId"));
			
			List<RpOldDeal> calculationData = crit.list();
			session.getTransaction().commit();
			AppLoger.APPLOGGER.info("updated");
			//session.close();
			return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(calculationData);
			}
			catch(Exception e)
			{
				AppLoger.APPLOGGER.info(e);
				session.getTransaction().rollback();
				//session.close();
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("No Data Found.");
			}
			
		}

