		private List<java.lang.Object> saveAutoFpDealStaffing(Session session, String strFilePath, FPManualDealAttachment fpData, Deal objDeal) throws IOException, EncryptedDocumentException, InvalidFormatException, ParseException 
		{
			AppLoger.APPLOGGER.info("Read Excel : in function uploadfpDealStaffingFile >> saveAutoFpDealStaffing");
			
			List<Object> lstResult = new ArrayList<Object>();
			List<BigDecimal> lstTotals = new ArrayList<BigDecimal>();
			/*********************************************************************************************/
			//TO run from Local Code 
//			InputStream stream = new FileInputStream(new File(strFilePath));
			/*********************************************************************************************/
			
			/*********************************************************************************************/
			//To run from Server code
			final String server  = "ftp://10.232.2.20/Rightprice/Ratecard";
			URL url;
			url = new URL(strFilePath);
			URLConnection con = url.openConnection();
			AppLoger.APPLOGGER.info("Read Excel : in function saveManualDealRPSummary: url flow Path :" + server + "/" + strFilePath );
			
			InputStream stream = con.getInputStream(); 
			/*********************************************************************************************/
			AppLoger.APPLOGGER.info("Fetch excel file to test on FTp server Started");
			Workbook wbRoles = WorkbookFactory.create(stream); 
					//WorkbookFactory.create(new File(strFilePath));
			AppLoger.APPLOGGER.info("FilFetch excel file to test on FTp server Successfull");
			
			Boolean isSheetPresent = false;
			
			Date dtDealStDate = getDate(objDeal.getProjectStartDate());
			Date dtDealEndDate = getDate(objDeal.getProjectEndDate());
			
			Calendar startCalendar = new GregorianCalendar();
			startCalendar.setTime(dtDealStDate);
			Calendar endCalendar = new GregorianCalendar();
			endCalendar.setTime(dtDealEndDate);
						
			int diffYear = endCalendar.get(Calendar.YEAR) - startCalendar.get(Calendar.YEAR);
			int intMonthDiff = diffYear * 12 + endCalendar.get(Calendar.MONTH) - startCalendar.get(Calendar.MONTH);
			if(diffYear == 0)
				intMonthDiff++;
			else 
				intMonthDiff = intMonthDiff + diffYear;
			
			//For loop to get the desired sheet
			for(int i=0; i<wbRoles.getNumberOfSheets(); i++)
			{
				Sheet sheet = wbRoles.getSheetAt(i);
				System.out.println("sheet Name: \t" + sheet.getSheetName());
				// if found sheet name "Staffing-Steady state"
				if(sheet.getSheetName().equalsIgnoreCase("Staffing-Steady state"))
				{
					isSheetPresent = true;
					
					int intBaseYear = 0;
					String strBaseMonth = "";
					
					//Delete existing records from  table [synprod].[RP_Deal_FPAutoYearData_STG]"
					Query qryDeleteYrData = session.createQuery("delete RPDealFPAutoYearDataSTG where RPDealVersionId = :RPDealVersionId and towerId = :towerId");
					qryDeleteYrData.setParameter("RPDealVersionId", fpData.getRpDealVersionId());
					qryDeleteYrData.setParameter("towerId", fpData.getDealAutoTowerId());
					int result = qryDeleteYrData.executeUpdate();
					
					BigDecimal dblDomesticTotal = null, dblDepTotal = null, dblOffTotal = null;
					
					
					for (int j = 2; j <= sheet.getLastRowNum(); j++) 
					{
						int columnCount = sheet.getRow(j).getLastCellNum();
						System.out.println("Column Count is............" + columnCount);
						Row row = sheet.getRow(j);
						RPDealFPAutoYearDataSTG objRPDealFPYr = new RPDealFPAutoYearDataSTG();
						
						//Read the roles till first occurrence of "Total Staffing"
						row.getCell(2).setCellType(CellType.STRING);
						if(j == 2)
						{
							row.getCell(4).setCellType(CellType.NUMERIC);
							dblDomesticTotal = BigDecimal.valueOf(row.getCell(4).getNumericCellValue());
							lstTotals.add(0, dblDomesticTotal.setScale(2, BigDecimal.ROUND_HALF_UP));
						}
						else if(j ==3)
						{
							row.getCell(4).setCellType(CellType.NUMERIC);
							dblDepTotal =  BigDecimal.valueOf(row.getCell(4).getNumericCellValue());
							lstTotals.add(1, dblDepTotal.setScale(2, BigDecimal.ROUND_HALF_UP));
						}
						else if(j == 4)
						{
							row.getCell(4).setCellType(CellType.NUMERIC);
							dblOffTotal = BigDecimal.valueOf(row.getCell(4).getNumericCellValue());
							lstTotals.add(2, dblOffTotal.setScale(2, BigDecimal.ROUND_HALF_UP));
						}
						else if(row.getCell(2) != null && row.getCell(2).getStringCellValue().toString().trim().equalsIgnoreCase("Total Staffing"))
							break;
						else if(row.getCell(1) != null && row.getCell(1).getCellType() != HSSFCell.CELL_TYPE_BLANK 
								&& (row.getCell(1).getStringCellValue().trim().equals("1")   || row.getCell(1).getStringCellValue().trim().equals("2")
										|| row.getCell(1).getStringCellValue().trim().equals("3") || row.getCell(1).getStringCellValue().trim().equals("4"))
								&& !row.getCell(2).getStringCellValue().toString().isEmpty())
						{
							AppLoger.APPLOGGER.info("Row Number :"+ (j+1)+" Visa ID : "+row.getCell(1).getStringCellValue()+ " Role : "+ row.getCell(2).getStringCellValue() + " " );
							
							int intEmptyCell = 0;
							int intMonthIndex = startCalendar.get(Calendar.MONTH);
							int intYear =  startCalendar.get(Calendar.YEAR);
							
							for(int k=5; k<=intMonthDiff+5; k++)
							{
								if(intEmptyCell == 12)
								{
									intMonthIndex=intMonthIndex-1;
									intEmptyCell = -1;
									AppLoger.APPLOGGER.info("Year Value : " + intYear);
								}
								else
								{	
									String mothName = new DateFormatSymbols().getMonths()[intMonthIndex].toString().substring(0, 3);									
									AppLoger.APPLOGGER.info("Month & Year: "+mothName+"" + intYear);
									switch(intEmptyCell)
									{
									case 0:
										AppLoger.APPLOGGER.info("Month 1: "+ new DateFormatSymbols().getMonths()[intMonthIndex].toString());
										objRPDealFPYr.setMonth1(row.getCell(k).getNumericCellValue());
										break;
									case 1:
										AppLoger.APPLOGGER.info("Month 2: "+ new DateFormatSymbols().getMonths()[intMonthIndex].toString());
										objRPDealFPYr.setMonth2(row.getCell(k).getNumericCellValue());
										break;
									case 2:
										AppLoger.APPLOGGER.info("Month 3: "+ new DateFormatSymbols().getMonths()[intMonthIndex].toString());
										objRPDealFPYr.setMonth3(row.getCell(k).getNumericCellValue());
										break;
									case 3:
										AppLoger.APPLOGGER.info("Month 4: "+ new DateFormatSymbols().getMonths()[intMonthIndex].toString());
										objRPDealFPYr.setMonth4(row.getCell(k).getNumericCellValue());
										break;
									case 4:
										AppLoger.APPLOGGER.info("Month 5: "+ new DateFormatSymbols().getMonths()[intMonthIndex].toString());
										objRPDealFPYr.setMonth5(row.getCell(k).getNumericCellValue());
										break;
									case 5:
										AppLoger.APPLOGGER.info("Month 6: "+ new DateFormatSymbols().getMonths()[intMonthIndex].toString());
										objRPDealFPYr.setMonth6(row.getCell(k).getNumericCellValue());
										break;
									case 6:
										AppLoger.APPLOGGER.info("Month 7: "+ new DateFormatSymbols().getMonths()[intMonthIndex].toString());
										objRPDealFPYr.setMonth7(row.getCell(k).getNumericCellValue());
										break;
									case 7:
										AppLoger.APPLOGGER.info("Month 8: "+ new DateFormatSymbols().getMonths()[intMonthIndex].toString());
										objRPDealFPYr.setMonth8(row.getCell(k).getNumericCellValue());
										break;
									case 8:
										AppLoger.APPLOGGER.info("Month 9: "+ new DateFormatSymbols().getMonths()[intMonthIndex].toString());
										objRPDealFPYr.setMonth9(row.getCell(k).getNumericCellValue());
										break;
									case 9:
										AppLoger.APPLOGGER.info("Month 10: "+ new DateFormatSymbols().getMonths()[intMonthIndex].toString());
										objRPDealFPYr.setMonth10(row.getCell(k).getNumericCellValue());
										break;
									case 10:
										AppLoger.APPLOGGER.info("Month 11: "+ new DateFormatSymbols().getMonths()[intMonthIndex].toString());
										objRPDealFPYr.setMonth11(row.getCell(k).getNumericCellValue());
										break;
									case 11:
										AppLoger.APPLOGGER.info("Month 12: "+  new DateFormatSymbols().getMonths()[intMonthIndex].toString());
										objRPDealFPYr.setMonth12(row.getCell(k).getNumericCellValue());
										break;
									default:
										break;
									}
									if(intEmptyCell == 11 || k == (intMonthDiff+5))	
									{
										//Save record
										objRPDealFPYr.setMasterRoleName(row.getCell(2).getStringCellValue());
										objRPDealFPYr.setClientRole(row.getCell(3).getStringCellValue());
										objRPDealFPYr.setRPDealVersionId(fpData.getRpDealVersionId());
										objRPDealFPYr.setTowerId(fpData.getDealAutoTowerId());
										objRPDealFPYr.setYear(intYear);
										objRPDealFPYr.setVisa_Id(Integer.valueOf(row.getCell(1).getStringCellValue()));
										 String syntelLanId= getSyntelId(this.auditTrails.getCurrentUser());
											if(syntelLanId.isEmpty() || syntelLanId==null)
											{
												objRPDealFPYr.setCreatedBy(this.auditTrails.getCurrentUser());
												objRPDealFPYr.setCreatedOn(this.auditTrails.getCurrentTimeStamp());
												objRPDealFPYr.setUpdatedBy(this.auditTrails.getCurrentUser());
												objRPDealFPYr.setUpdatedOn(this.auditTrails.getCurrentTimeStamp());
											}
											else
											{
												objRPDealFPYr.setCreatedBy(syntelLanId);
												objRPDealFPYr.setCreatedOn(this.auditTrails.getCurrentTimeStamp());
												objRPDealFPYr.setUpdatedBy(syntelLanId);
												objRPDealFPYr.setUpdatedOn(this.auditTrails.getCurrentTimeStamp());
											}
										session.save(objRPDealFPYr);
										
										objRPDealFPYr = new RPDealFPAutoYearDataSTG();
										intYear++;
									}
									
								}
											
								intMonthIndex++;
								
								if(intMonthIndex==12)
								{
									intMonthIndex=0;
									//intYear++;
								}								
								intEmptyCell++;
							}
							
						}
					}
				}
			}
			
			wbRoles.close();
			stream.close();
			
			//Update data in [synprod].[RP_Deal_Staffing_Details]
			ProcedureCall qryUpdateFpAutoDealStaffing = null;
			qryUpdateFpAutoDealStaffing = session.createStoredProcedureCall("[synprod].[RP_UpdateDealStaffingFPAuto]");
			qryUpdateFpAutoDealStaffing.registerParameter("RP_Deal_Version_Id", Integer.class, ParameterMode.IN).bindValue(fpData.getRpDealVersionId());
			qryUpdateFpAutoDealStaffing.registerParameter("Tower_Id", Integer.class, ParameterMode.IN).bindValue(fpData.getDealAutoTowerId());
			 String syntelLanId= getSyntelId(this.auditTrails.getCurrentUser());
				if(syntelLanId.isEmpty() || syntelLanId==null)
				{
					qryUpdateFpAutoDealStaffing.registerParameter("strUpdatedBy", String.class, ParameterMode.IN).bindValue(this.auditTrails.getCurrentUser());
				}
				else
				{
					qryUpdateFpAutoDealStaffing.registerParameter("strUpdatedBy", String.class, ParameterMode.IN).bindValue(syntelLanId);
				}
			ProcedureOutputs spUpdateDealStaffingResult = qryUpdateFpAutoDealStaffing.getOutputs();
			
			// to update the totals for inserted data.
			ProcedureCall qryUpdateFpDealStaffingTotal = session.createStoredProcedureCall("[synprod].[RP_FP_deal_staffing_summarization]");
			qryUpdateFpDealStaffingTotal.registerParameter("RPDealVersionId", Integer.class, ParameterMode.IN).bindValue(fpData.getRpDealVersionId());			
			ProcedureOutputs spUpdateFPAutoDealStaffingTotal = qryUpdateFpDealStaffingTotal.getOutputs();
			
			lstResult.add(0,isSheetPresent);
			if(lstTotals.size() > 0)
			{
				for(BigDecimal dblTotal:lstTotals)
				{
					lstResult.add(dblTotal);
				}
				
			}
			
			return lstResult;
			
		}
		
		private static Date getDate(String strdate)
		{		
			SimpleDateFormat sdf = 
			        new SimpleDateFormat("yyyy-MM-dd");
			    Date date = null;
				try 
				{
					date = sdf.parse(strdate);
				} 
				catch (ParseException e) 
				{				
					e.printStackTrace();
				} 
			
			return date;
		}
