	    public List rcInfoTnM(int dealId,Session session) {
			
	    	String get_entity = " select rcd.RC_Id ,rcd.RC_Name,rcd.Expected_Onsite_Resource_Percentage, rcd.Expected_Offshore_Resource_Percentage,"
					+ " case when rcd.Calculated_GM_Percentage_Post_Discount is NOT NULL then rcd.Calculated_GM_Percentage_Post_Discount ELSE 0 END AS Calculated_GM_Percentage_Post_Discount, "
					+ " rc.RC_Weightage,rcd.Blended_Rate,rcd.Blended_Cost,  "
					+ "rc.RC_Weightage * rcd.Blended_Rate* 0.01 as weightageXbl_rate ,rc.RC_Weightage * rcd.Blended_Cost * 0.01 as weightageXbl_cost, "
					+ " case when rc.RC_Weightage * rcd.Blended_Rate = 0 then  rc.RC_Weightage * rcd.Blended_Rate else  "
					+ " ((rc.RC_Weightage * rcd.Blended_Rate - rc.RC_Weightage * rcd.Blended_Cost)/(rc.RC_Weightage * rcd.Blended_Rate))*100 end as final_GM "
					+ " from [synprod].[RP_Rate_Card_Details] as rcd, synprod.RP_Deal_RateCards rc  where rcd.is_active=1 and rcd.RC_Id = rc.Deal_Rc_Id "
					+ "and rc.RP_deal_version_id= "+dealId+" and rc.is_active=1 and RC_Id in (select Deal_RC_Id "
					+ "from synprod.RP_Deal_RateCards where is_active=1 and RP_deal_version_id= "+dealId+" ) ";
			//System.out.println("getKnowledgeName_saved==================================="+get_entity);
			Query quer = session.createSQLQuery(get_entity).addEntity(RateCardSummaryDataNew.class);
			List entityList = quer.list();
			return entityList;
		}
	    
	    private Map<Integer, List<Double>>  rcOFshoreonsiteVlaues(int dealId,Session session) 
	    {
	    	Map<Integer, List<Double>> map = new HashMap<Integer, List<Double>>();
			List<Double> onsitelst = new ArrayList<Double>();
			List<Double> ofShorelst = new ArrayList<Double>();
			List lstTotalOffshore = null;
			int rcId=0;
			int gmPer=0;
			
			Double staffings=0.0,totaloffshore=0.0;
			Double onsitesper=0.0,ofshoresPer=0.0,onsiteper=0.0,ofshorePer=0.0;
			long onsites=0,offshores=0;
			
			String get_entity = "  Select (select sum(Country_Id) from [synprod].[RP_Deal_Staffing_Details] "
					+ " where RP_Deal_Version_Id="+dealId+" and Is_Active=1 and Sum_Total_Type=6) As TEMP_ID ,"
					+ " (select sum(Yearly_Sum_Total) from [synprod].[RP_Deal_Staffing_Details] "
					+ " where RP_Deal_Version_Id= "+dealId+" and Is_Active=1 and Sum_Total_Type=6) As total_staffing,"
					+ "(select sum(Yearly_Sum_Total) from [synprod].[RP_Deal_Staffing_Details]  "
					+ " where RP_Deal_Version_Id= "+dealId+" and Is_Active=1 and Sum_Total_Type=1 and Visa_Id = 4) As total_offshore ";
			System.out.println("getStaffingPercentage==================================="+get_entity);
				Query quer = session.createSQLQuery(get_entity).addEntity(StaffingPercentage.class);
							List stafList = quer.list();
							if(!stafList.isEmpty()){
							AppLoger.APPLOGGER.info("stafList List :");
							for (Object object : stafList) {
								if(object!=null){
								StaffingPercentage staffingPer = (StaffingPercentage) object;
								totaloffshore=staffingPer.getTotalOffshore();
								staffings=staffingPer.getTotalStaffing();
							}
						   }
							if(totaloffshore!=null&&staffings!=null){
								if(staffings==0 || staffings==0.0)
								{
									 
									ofShorelst.add(1.7976931348623157E308);
									onsitelst.add(1.7976931348623157E308);
								}
								else{
								ofshoresPer =	(totaloffshore/staffings)*100;
								ofShorelst.add(ofshoresPer);
								onsitesper =  (100 - ofShorelst.get(0));
								onsitelst.add(onsitesper);
								}
							}
							else{
								ofShorelst.add(0.0);
								onsitelst.add(0.0);
							}
						   }
							else {
								ofShorelst.add(0.0);
								onsitelst.add(0.0);
							}
							map.put(1,ofShorelst);
							map.put(2,onsitelst);
						 	
							return map.isEmpty() ? null : map;  

		} 
	    
	    
