		@Override
		public ResponseEntity<Object> getDealStatusData(MyDashboardDeal[] dealData) {
			AppLoger.APPLOGGER.info("inside getRateCardData impl");
			Session session = this.sessionFactory.getCurrentSession();
			List<Integer> customerId = new ArrayList<Integer>();
			List<String> userType = new ArrayList<String>();
			List<Integer>dealStatusValue = new ArrayList<Integer>();
			for (MyDashboardDeal getDealData : dealData) {
				customerId.add(getDealData.getCustomerId());
				if (getDealData.getUserType() != null) {
					if(userType.isEmpty())
					{
						userType.add(getDealData.getUserType());
					}
				}
				if(getDealData.getDealStatusIdWL() != null)
				{
					dealStatusValue.add(getDealData.getDealStatusIdWL());
				}
			}
			Criteria crit = session.createCriteria(MyDashboardDeal.class, "myDashboardDeal").add(Restrictions.eq("isActive",1));
			crit.createCriteria("dealcrmstagesdata2", "dealcrmstagesdata2").add(Restrictions.eq("dealStatusId", dealStatusValue.get(0))).add(Restrictions.eq("isActive",1))
					.add(Restrictions.in("customerId", customerId))
					.addOrder(Order.desc("updatedDate"));
			crit.createCriteria("appCode","appCode").add(Restrictions.like("codeType", "%Currency%"));
			List<MyDashboardDeal> crmStagesData = crit.list();
			if (!crmStagesData.isEmpty()) {
				//session.close();
				return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(crmStagesData);
			} else {
				//session.close();
				return ResponseEntity.status(204).contentType(MediaType.TEXT_PLAIN).body(crmStagesData);
			}
		}

