		@Override
		public ResponseEntity<Object> viewRolesExportDetails(int towerId, int dealVersionId) 
		{
			Session session = this.sessionFactory.getCurrentSession();
			
			try 
			{
				Map<String, Object> data = new HashMap<>();
				
				Criteria critDeal = session.createCriteria(Deal.class, "DealData").add(Restrictions.eq("isActive", 1)).add(Restrictions.eq("rpDealVersionId", dealVersionId));
				List<Deal> lstDealDetails = critDeal.list();		
				
				String strProjectStDate =  lstDealDetails.get(0).getProjectStartDate();
				  
				Date dtDealStDate = getDate(strProjectStDate);
				Calendar startCalendar = new GregorianCalendar();
				startCalendar.setTime(dtDealStDate);
				
				int intDealStartYr = startCalendar.get(Calendar.YEAR);
				
				Criteria critStaffing = session.createCriteria(StaffingDetails.class, "StaffingDetails").add(Restrictions.eq("isActive", 1))
						.add(Restrictions.eq("rpDealVersionId", dealVersionId)).add(Restrictions.eq("dealTowerId", towerId))
						.add(Restrictions.eq("sumTotalType", 0)).add(Restrictions.eq("visaId", 1)).add(Restrictions.not(Restrictions.eq("monthYearHeader", "Summary")))
						.add(Restrictions.eq("staffingYear", intDealStartYr));
				List lstStaffing = critStaffing.list();
				
				data.put("dealData", lstDealDetails);
				data.put("staffingDetails", lstStaffing);
				
				return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(data);
			} 
			catch(Exception e) 
			{
				return ResponseEntity.status(204).contentType(MediaType.TEXT_PLAIN).body("No Data found");
			}
		}
		

