		private void processExcelData_GFT(InputStream stream, RateCardDetails rateCardApprovalDetails,Session session, int intCityId, int countryId) throws Exception 
		{
			try
			{
				//Create workbook object from byte input stream
				XSSFWorkbook workbook = new XSSFWorkbook(stream);
				
				for(int i=0; i<workbook.getNumberOfSheets(); i++)
				{
					XSSFSheet sheet = workbook.getSheetAt(i);
					System.out.println("sheet Name: \t" + sheet.getSheetName());			
					
					if(sheet.getSheetName().equals("Final T&M"))
					{					
						//1. Read roles data save RP_Insert_Rate_Card_Roles_STG
						ArrayList<RateCardRolesGFTSTG> arrLiRcRolesGFT_STG = new ArrayList<RateCardRolesGFTSTG>();
						for (int j = 3; j <= sheet.getLastRowNum(); j++) 
						{
							RateCardRolesGFTSTG objRCRoleStg =  new RateCardRolesGFTSTG();
							
							double dblRevOnsiteRate = 0.0;
							double dblRevOffshoreRate = 0.0;
							
							try
							{
								dblRevOnsiteRate = sheet.getRow(j).getCell(38).getNumericCellValue();
							}
							catch(Exception Ex)
							{
								dblRevOnsiteRate = 0.0;
							}
							
							try
							{
								dblRevOffshoreRate = sheet.getRow(j).getCell(39).getNumericCellValue();
							}
							catch(Exception Ex)
							{
								dblRevOffshoreRate = 0.0;
							}
							
							sheet.getRow(j).getCell(1).setCellType(CellType.STRING);
							sheet.getRow(j).getCell(9).setCellType(CellType.STRING);
							
							if(sheet.getRow(j).getCell(1).getRichStringCellValue().toString().isEmpty() 
									|| sheet.getRow(j).getCell(1).getRichStringCellValue().toString().equals("0"))
								break;
							
							// 6. Insert this data in temporary table
							objRCRoleStg.setRcId(rateCardApprovalDetails.getRcId());
							objRCRoleStg.setRole(sheet.getRow(j).getCell(1).getRichStringCellValue().toString());
							objRCRoleStg.setClientRole(sheet.getRow(j).getCell(9).getRichStringCellValue().toString());
							objRCRoleStg.setOnsiteProposedClientRate(dblRevOnsiteRate);
							objRCRoleStg.setOffshoreProposedClientRate(dblRevOffshoreRate);
							 String syntelLanId= getSyntelId(this.auditTrails.getCurrentUser());
								if(syntelLanId.isEmpty() || syntelLanId==null)
								{
									objRCRoleStg.setCreatedBy(this.auditTrails.getCurrentUser());
									objRCRoleStg.setUpdatedBy(this.auditTrails.getCurrentUser());
								}
								else
								{
								objRCRoleStg.setCreatedBy(syntelLanId);
								objRCRoleStg.setUpdatedBy(this.auditTrails.getCurrentUser());
								}
							arrLiRcRolesGFT_STG.add(objRCRoleStg);
						}
						//  save RP_Insert_Rate_Card_Roles_STG
						//  Save data in Rp_SaveRateCardRoles
						// {CALL [synprod].[RP_Calculate_Role_Wise_Yearly_GM_Revenue_Cost_For_Rate_Card_Manual](:RC_Id,:Country_Id,:City_Id,:strCreatedBy)
						uploadMannualRCData_GFT(arrLiRcRolesGFT_STG,session,countryId,intCityId, rateCardApprovalDetails.getRcId());
						
						//UpdateRevisedRates_GFT(sheet,rateCardApprovalDetails,session,countryId,intCityId);
					}
				}
				workbook.close();
				stream.close();
			}
			catch(Exception ex)
			{
				ex.printStackTrace();
				AppLoger.APPLOGGER.info("Error Occured in processExcelData: StackTrace :" + ex.getStackTrace());
				AppLoger.APPLOGGER.info("Error Occured in processExcelData: Error" + ex.getMessage());
				throw new Exception("Error Occured in processExcelData: " + ex.getMessage()); 
			}
			
		}
		
		private void uploadMannualRCData_GFT(ArrayList<RateCardRolesGFTSTG> arrLiRcRolesGFT_STG, Session session, int countryId, int intCityId, int intRcId) throws Exception {
			AppLoger.APPLOGGER.info("Inside RightPriceRepositoryImplementaion ==> updateApprovalDataForRateCard ==> uploadMannualRCData"); 
			
			// to delete records from stg
			Query qryDeleteRC_STG = session.createQuery("delete RateCardRolesGFTSTG where rcId = :rcId and countryId = :countryId and cityId = :cityId");
			qryDeleteRC_STG.setParameter("rcId", intRcId);
			qryDeleteRC_STG.setParameter("countryId", countryId);
			qryDeleteRC_STG.setParameter("cityId", intCityId);		
			int result = qryDeleteRC_STG.executeUpdate();
			
			int intCounter = 0;
			for (RateCardRolesGFTSTG objRcRolesGFT_STG : arrLiRcRolesGFT_STG) 
			{
				intCounter++;
				if(objRcRolesGFT_STG.getClientRole() == null || objRcRolesGFT_STG.getClientRole().length() == 0 || objRcRolesGFT_STG.getClientRole().isEmpty())
					objRcRolesGFT_STG.setClientRole(Integer.toString(intCounter));
				
				ProcedureCall query = session.createStoredProcedureCall("[synprod].[RP_Insert_Rate_Card_Roles_STG]");

				query.registerParameter("RC_Id", Integer.class, ParameterMode.IN).bindValue(objRcRolesGFT_STG.getRcId());
	            query.registerParameter("strMasterRole", String.class, ParameterMode.IN).bindValue(objRcRolesGFT_STG.getRole());
	            query.registerParameter("strClientRole", String.class, ParameterMode.IN).bindValue(objRcRolesGFT_STG.getClientRole());
	            query.registerParameter("dblRevOnsiteRate", Double.class, ParameterMode.IN).bindValue(objRcRolesGFT_STG.getOnsiteProposedClientRate());
	            query.registerParameter("dblRevOffshoreRate", Double.class, ParameterMode.IN).bindValue(objRcRolesGFT_STG.getOffshoreProposedClientRate());
	            query.registerParameter("intCountryId", Integer.class, ParameterMode.IN).bindValue(countryId);
	            query.registerParameter("intCityId", Integer.class, ParameterMode.IN).bindValue(intCityId);	            
	            String syntelLanId= getSyntelId(this.auditTrails.getCurrentUser());
				if(syntelLanId.isEmpty() || syntelLanId==null)
				{
					query.registerParameter("strCreatedBy",  String.class, ParameterMode.IN).bindValue(this.auditTrails.getCurrentUser());
		            query.registerParameter("strUpdatedBy",  String.class, ParameterMode.IN).bindValue(this.auditTrails.getCurrentUser());
				}
				else
				{
	            query.registerParameter("strCreatedBy",  String.class, ParameterMode.IN).bindValue(syntelLanId);
	            query.registerParameter("strUpdatedBy",  String.class, ParameterMode.IN).bindValue(syntelLanId);
				}
	            ProcedureOutputs procedureResult = query.getOutputs();
			}
			
			AppLoger.APPLOGGER.info("Executed SP [RP_Insert_Rate_Card_Roles_STG] successfully");
			
			AppLoger.APPLOGGER.info("Inside RightPriceRepositoryImplementaion ==> uploadMannualRCData_GFT ==> Calling stored procedure [synprod].[RP_SaveRateCardRoles]");
			Query qrySaveRoles = session.createSQLQuery("{CALL [synprod].[RP_SaveRateCardRoles](:RC_Id)}");
			qrySaveRoles.setParameter("RC_Id",  arrLiRcRolesGFT_STG.get(0).getRcId());
			int qryRows = qrySaveRoles.executeUpdate();
			AppLoger.APPLOGGER.info("Executed Rows from Stored Procedure [synprod].[RP_SaveRateCardRoles] ****************"+qryRows);
			
			
			AppLoger.APPLOGGER.info("Inside RightPriceRepositoryImplementaion ==> uploadManualRateCard ==>uploadMannualRCData_GFT ==> Calling stored procedure [synprod].[RP_Update_Rate_Card_Roles_Wise_RCGM_Yearly_Summary]");
			Query qryUpdateSummary = session.createSQLQuery("{CALL [synprod].[RP_Calculate_Role_Wise_Yearly_GM_Revenue_Cost_For_Rate_Card_Manual](:RC_Id,:Country_Id,:City_Id,:strCreatedBy)}");
			qryUpdateSummary.setParameter("RC_Id",  arrLiRcRolesGFT_STG.get(0).getRcId());
			qryUpdateSummary.setParameter("Country_Id",  countryId);
			qryUpdateSummary.setParameter("City_Id",  intCityId);
			qryUpdateSummary.setParameter("strCreatedBy",  arrLiRcRolesGFT_STG.get(0).getCreatedBy());
			
			List lstSummeryResult = qryUpdateSummary.list();
			AppLoger.APPLOGGER.info("RESULT");
			AppLoger.APPLOGGER.info(lstSummeryResult);
			if(!lstSummeryResult.get(0).toString().toLowerCase().trim().equals("success"))
			{
				throw new Exception("[RP_Calculate_Role_Wise_Yearly_GM_Revenue_Cost_For_Rate_Card_Manual] returned Failure");
			}
			AppLoger.APPLOGGER.info("Executed Rows from Stored Procedure [synprod].[synprod].[RP_Update_Rate_Card_Roles_Wise_RCGM_Yearly_Summary] ****************"+qryRows);
			
			// Call RP_UpdateRevisedRate
			AppLoger.APPLOGGER.info("Inside RightPriceRepositoryImplementaion ==> uploadMannualRCData_GFT "
					+ "==>Calling stored procedure [synprod].[RP_UpdateRevisedRates]");
			ProcedureCall qryUpdateRates = session.createStoredProcedureCall("[synprod].[RP_UpdateRevisedRates]");
			qryUpdateRates.registerParameter("RC_Id", Integer.class, ParameterMode.IN).bindValue(arrLiRcRolesGFT_STG.get(0).getRcId());
			String syntelLanId= getSyntelId(this.auditTrails.getCurrentUser());
			if(syntelLanId.isEmpty() || syntelLanId==null)
			{
				qryUpdateRates.registerParameter("strUpdatedBy", String.class, ParameterMode.IN).bindValue(this.auditTrails.getCurrentUser());
			}
			else
			{
			qryUpdateRates.registerParameter("strUpdatedBy", String.class, ParameterMode.IN).bindValue(syntelLanId);
			}
			ProcedureOutputs procedureResult = qryUpdateRates.getOutputs();
			AppLoger.APPLOGGER.info("Executed SP [RP_UpdateRevisedRates]successfully");
			
		}
		
		
		private void UpdateRevisedRates_GFT(XSSFSheet sheet, RateCardDetails rateCardApprovalDetails, Session session, int countryId, int intCityId) throws Exception  
		{
			
			// To do
			/*1. Read roles data save RP_Insert_Rate_Card_Roles_STG
			2. Save data in Rp_SaveRateCardRoles
			3.{CALL [synprod].[RP_Calculate_Role_Wise_Yearly_GM_Revenue_Cost_For_Rate_Card_Manual](:RC_Id,:Country_Id,:City_Id,:strCreatedBy)
			4. Call RP_UpdateRevisedRate	*/
			
			try
			{
				for (int j = 3; j <= sheet.getLastRowNum(); j++) 
				{
					sheet.getRow(j).getCell(1).setCellType(CellType.STRING);
					sheet.getRow(j).getCell(9).setCellType(CellType.STRING);
					
					if(sheet.getRow(j).getCell(1).getRichStringCellValue().toString().isEmpty()
							|| sheet.getRow(j).getCell(1).getRichStringCellValue().toString().equals("0"))
						break;
					
					double dblRevOnsiteRate = 0.0;
					double dblRevOffshoreRate = 0.0;
					
					try
					{
						dblRevOnsiteRate = sheet.getRow(j).getCell(38).getNumericCellValue();
					}
					catch(Exception Ex)
					{
						dblRevOnsiteRate = 0.0;
					}
					
					try
					{
						dblRevOffshoreRate = sheet.getRow(j).getCell(39).getNumericCellValue();
					}
					catch(Exception Ex)
					{
						dblRevOffshoreRate = 0.0;
					}
					
					// 4. Call RP_UpdateRevisedRate
					AppLoger.APPLOGGER.info("Inside RightPriceRepositoryImplementaion ==> uploadManualRateCard ==> UpdateRevisedRates_GFT "
							+ "==> Calling stored procedure [synprod].[RP_UpdateRevisedRates]");
					ProcedureCall query = session.createStoredProcedureCall("[synprod].[RP_UpdateRevisedRates]");
					query.registerParameter("City_Id", Integer.class, ParameterMode.IN) .bindValue(intCityId);
					query.registerParameter("RC_Id", Integer.class, ParameterMode.IN).bindValue(rateCardApprovalDetails.getRcId());
					query.registerParameter("strRoleCode", String.class, ParameterMode.IN).bindValue(sheet.getRow(j).getCell(1).getRichStringCellValue().toString());
					query.registerParameter("strClientRole", String.class, ParameterMode.IN).bindValue(sheet.getRow(j).getCell(9).getRichStringCellValue().toString());
					query.registerParameter("dblRevOnsiteRate", Double.class, ParameterMode.IN).bindValue(dblRevOnsiteRate);
					query.registerParameter("dblRevOffshoreRate", Double.class, ParameterMode.IN).bindValue(dblRevOffshoreRate);
					String syntelLanId= getSyntelId(this.auditTrails.getCurrentUser());
					if(syntelLanId.isEmpty() || syntelLanId==null)
					{
						query.registerParameter("strCreatedBy", String.class, ParameterMode.IN).bindValue(this.auditTrails.getCurrentUser());
						query.registerParameter("strUpdatedBy", String.class, ParameterMode.IN).bindValue(this.auditTrails.getCurrentUser());
					}
					else
					{
					query.registerParameter("strCreatedBy", String.class, ParameterMode.IN).bindValue(syntelLanId);
					query.registerParameter("strUpdatedBy", String.class, ParameterMode.IN).bindValue(syntelLanId);
					}
					
					ProcedureOutputs procedureResult = query.getOutputs();
					AppLoger.APPLOGGER.info("Executed  Stored Procedure [synprod].[RP_UpdateRevisedRates]  successfully");
				}
				
			}
			catch(Exception ex)
			{
				ex.printStackTrace();
				AppLoger.APPLOGGER.info("Error Occured in saveFinalTandMData: StackTrace :" + ex.getStackTrace());
				AppLoger.APPLOGGER.info("Error Occured in saveFinalTandMData: Error" + ex.getMessage());
				throw new Exception("Error Occured in saveFinalTandMData: " + ex.getMessage()); 
			}
		}
		
		
