		@Override
		 public ResponseEntity<Object> getAtosRcData() {
			Session session = this.sessionFactory.getCurrentSession();
			try {
			String qryForRateCardName = "select ID,loc.RC_Location_Id,rcDetails.RC_ID,rcDetails.RC_NAME,rcDetails.RC_START_DATE,rcDetails.RC_END_DATE,rcDetails.Current_Approval_Status, "
					+"rcDetails.CREATED_BY,rcDetails.CREATED_ON,rcDetails.UPDATED_BY,rcDetails.UPDATED_ON, "
					+"rcDetails.Expected_Onsite_Resource_Percentage,rcDetails.Expected_Offshore_Resource_Percentage, "
					+"rcDetails.VERTICAL_ID,rcDetails.Calculated_GM_Percentage_Post_Discount, "
					+"rcDetails.CUSTOMER_ID,rcDetails.Is_Atos,loc.Country_Id,loc.City_Id,objMap.Attachment_Id "
					+",con.Country_Name,city.City_Name,rcDetails.Is_Active,vert.vertical_Name,cust.CUSTOMER_Name "
					+" from synprod.RP_RATE_CARD_DETAILS rcDetails "
					+"join SYNPROD.RP_RATE_CARD_LOCATION loc on rcDetails.RC_ID = loc.RC_ID "
					+"join synprod.MST_RP_Country con on loc.Country_Id = con.Country_Id "
					+"join synprod.MST_RP_City city on loc.City_Id = city.City_Id "
					+"join [synprod].[MST_RP_Vertical] vert on rcDetails.vertical_ID = vert.vertical_ID "
					+"join synprod.MST_RP_Customer cust on  rcDetails.CUSTOMER_id = cust.CUSTOMER_id "
					+ "Left join [synprod].[RP_Attachments] objMap on rcDetails.RC_ID = objMap.Version_Id "
					+ "join [synprod].[RP_Object] obj on objMap.Attachment_Id  = obj.Object_Id "
					+"where rcDetails.Is_Atos = 1 "
					+ "and obj.is_Active = 1 "
					+ "and objMap.Is_Active = 1 "
					+ "Order By rcDetails.RC_ID";

				
				Query crit = session.createSQLQuery(qryForRateCardName).addEntity(AtosRateCardDetails.class);		
				
				List<AtosRateCardDetails> ratecardNamelist = crit.list();
				
				if (!ratecardNamelist.isEmpty()) {
					return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(ratecardNamelist);
				} else {
					return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body(ratecardNamelist);
				}
			} catch (Exception e) {
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently Facing Techinal issue"+e.getMessage());
			}
}
		
