		@Override
		public ResponseEntity<Object> updatePracticeDetails(MasterPractice practiceDetails) {
			AppLoger.APPLOGGER.info("inside impl");
			AppLoger.APPLOGGER.info("Query Count function: " + 11);
			Session session = this.sessionFactory.getCurrentSession();
			session.beginTransaction();
			int insertId = 0;
			
			try{		
				if(checkPracticeName(practiceDetails)){
					return ResponseEntity.status(203).contentType(MediaType.TEXT_PLAIN).body("Practice already exist");
				}
				  if(practiceDetails.getDescription()==null||practiceDetails.getDescription()==""){
					  Query qryPracticeUpdate = session.createQuery("UPDATE MasterPractice set  isActive = :isActive, "
								+ "updatedBy = :updatedBy, updatedOn=:updatedOn where practiceId = :practiceId");
						qryPracticeUpdate.setParameter("isActive", practiceDetails.getIsActive());
						qryPracticeUpdate.setParameter("updatedBy", practiceDetails.getUpdatedBy());
						qryPracticeUpdate.setParameter("updatedOn", practiceDetails.getUpdatedOn());
						qryPracticeUpdate.setParameter("practiceId", practiceDetails.getPracticeId());
						
						insertId = qryPracticeUpdate.executeUpdate();
				  }
				  else{
					  Query qryPracticeUpdate = session.createQuery("UPDATE MasterPractice set description=:description, isActive = :isActive, "
								+ "updatedBy = :updatedBy, updatedOn=:updatedOn where practiceId = :practiceId");
						qryPracticeUpdate.setParameter("description", practiceDetails.getDescription());
						qryPracticeUpdate.setParameter("isActive", practiceDetails.getIsActive());
						qryPracticeUpdate.setParameter("updatedBy", practiceDetails.getUpdatedBy());
						qryPracticeUpdate.setParameter("updatedOn", practiceDetails.getUpdatedOn());
						qryPracticeUpdate.setParameter("practiceId", practiceDetails.getPracticeId());
						
						insertId = qryPracticeUpdate.executeUpdate();
				  }
					
					
				
				
				AppLoger.APPLOGGER.info("updated");
				

				
				session.getTransaction().commit();
				
				return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body("Data Inserted Successfully");
			}
			catch (Exception e) 
			{
				session.getTransaction().rollback();
				throw e;
			} finally {
				//session.close();
			}
		}
		
		@Override
		public ResponseEntity<java.lang.Object> getFileredAtosRcData(int country, String rcStartDate, String rcEndDate, int currentApStatus) {
			
			Session session = this.sessionFactory.getCurrentSession();
			Map<String, Object> params = new HashMap<String,Object>();
			try {
			String qryForRateCardName = "select  ID,loc.RC_Location_Id,rcDetails.RC_ID,rcDetails.RC_NAME,rcDetails.RC_START_DATE,rcDetails.RC_END_DATE,rcDetails.Current_Approval_Status, "
					+"rcDetails.CREATED_BY,rcDetails.CREATED_ON,rcDetails.UPDATED_BY,rcDetails.UPDATED_ON, "
					+"rcDetails.Expected_Onsite_Resource_Percentage,rcDetails.Expected_Offshore_Resource_Percentage, "
					+"rcDetails.VERTICAL_ID,rcDetails.Calculated_GM_Percentage_Post_Discount, "
					+"rcDetails.CUSTOMER_ID,rcDetails.Is_Atos,loc.Country_Id,loc.City_Id,objMap.Attachment_Id "
					+",con.Country_Name,city.City_Name,rcDetails.Is_Active,vert.vertical_Name,cust.CUSTOMER_Name "
					+" from synprod.RP_RATE_CARD_DETAILS rcDetails "
					+"join SYNPROD.RP_RATE_CARD_LOCATION loc on rcDetails.RC_ID = loc.RC_ID "
					+"join synprod.MST_RP_Country con on loc.Country_Id = con.Country_Id "
					+"join synprod.MST_RP_City city on loc.City_Id = city.City_Id "
					+"join [synprod].[MST_RP_Vertical] vert on rcDetails.vertical_ID = vert.vertical_ID "
					+"join synprod.MST_RP_Customer cust on  rcDetails.CUSTOMER_id = cust.CUSTOMER_id "
					+ "Left join [synprod].[RP_Attachments] objMap on rcDetails.RC_ID = objMap.Version_Id "
					+ "join [synprod].[RP_Object] obj on objMap.Attachment_Id  = obj.Object_Id "
					+"where rcDetails.Is_Atos = 1 "
					+ "and obj.is_Active = 1 "
					+ "and objMap.Is_Active = 1 ";
				
				if(country != 0){
					qryForRateCardName += " and loc.Country_Id =:country"; 
					params.put( "country", country );
				}
				
				if(!(rcStartDate.equals("null"))){
					qryForRateCardName += " and cast(rcDetails.RC_START_DATE as Date) >=:rcStartDate and cast(rcDetails.RC_END_DATE as Date) <=:rcEndDate"; 
					params.put( "rcStartDate", rcStartDate );
					params.put( "rcEndDate", rcEndDate );
				}
				

				
				if (currentApStatus == 0) 
				{
					qryForRateCardName += " and rcDetails.Current_Approval_Status = 3";
				} else if (currentApStatus == 1) 
				{

					String currentTime = this.auditTrails.getCurrentTimeStamp();
					String dateformat[]= new String[2];  
					String dateArray[]= new String[2];  
					
					dateformat = currentTime.split(" ");
					dateArray =dateformat[0].split("-");
					String currentDate =  dateArray[2]+"-"+dateArray[0]+"-"+dateArray[1]; 
					
					qryForRateCardName += " and :currentDate between cast(rcDetails.RC_START_DATE as Date)  and cast(RC_END_DATE as Date)  ";
					params.put( "currentDate", currentDate);
					
					//qryForRateCardName += " and (rcDetails.Current_Approval_Status = 1 OR rcDetails.Current_Approval_Status = 2) ";
				}else if (currentApStatus == 2) 
				{
					String currentTime = this.auditTrails.getCurrentTimeStamp();
					String dateformat[]= new String[2];  
					String dateArray[]= new String[2];  
					
					dateformat = currentTime.split(" ");
					dateArray =dateformat[0].split("-");
					String currentDate =  dateArray[2]+"-"+dateArray[0]+"-"+dateArray[1]; 
					
					qryForRateCardName += " and cast(RC_END_DATE as Date) <=:currentDate  ";
					params.put( "currentDate", currentDate);
				}
				qryForRateCardName += " Order By rcDetails.RC_ID";
				
				Query crit = session.createSQLQuery(qryForRateCardName).addEntity(AtosRateCardDetails.class);		
				
				   for (String str : crit.getNamedParameters())
			        {
					   crit.setParameter( str, params.get( str ) );
			        }
				   
				
				List<AtosRateCardDetails> ratecardNamelist = crit.list();

				
				if (!ratecardNamelist.isEmpty()) {
					return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(ratecardNamelist);
				} else {
					return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body(ratecardNamelist);
				}
			} catch (Exception e) {
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently Facing Techinal issue"+e.getMessage());
			}
			
			
		
		
		}

