		@Override
		public ResponseEntity<java.lang.Object> getUpdatedApprovalMatrix(int rpVrsId) {
			AppLoger.APPLOGGER.info("================inside getApprovalMatrixWhatIf===================");
			Session session = this.sessionFactory.getCurrentSession();
			Transaction t = session.beginTransaction();
			try {
				
				Criteria check = session.createCriteria(FpDeal.class, "fp").add(Restrictions.eq("rpDealVersionId", rpVrsId));
				List<FpDeal> fpDetails = check.list();
				int currentApprovalStatus = 8;
				int updateId = 0;
				if(fpDetails.size() > 0) {
					if(fpDetails.get(0).getProjectIndustry() == 2) {
						Query query = session.createQuery("update FpDeal set level1ApproverRoleId =:level1ApproverRoleId,level2ApproverRoleId=:level2ApproverRoleId,level3ApproverRoleId=:level3ApproverRoleId,currentApprovalStatus = :currentApprovalStatus, updatedBy = :updatedBy, updatedDate = :updatedDate, pageTrackerStatus = :pageTrackerStatus where rpDealVersionId = :rpDealVersionId AND isActive = 1");
						query.setParameter("level1ApproverRoleId", 4);
						query.setParameter("level2ApproverRoleId", 6);
						query.setParameter("level3ApproverRoleId", 13);
						query.setParameter("currentApprovalStatus", currentApprovalStatus);
						query.setParameter("updatedBy", fpDetails.get(0).getUpdatedBy());
						query.setParameter("updatedDate", fpDetails.get(0).getUpdatedDate());
						query.setParameter("rpDealVersionId", rpVrsId);
						query.setParameter("pageTrackerStatus", 6);
						updateId = query.executeUpdate();
					} else {
						Query storefpProcQuery = session.createSQLQuery("{CALL synprod.RP_SET_Approval_Levels_for_FP_Deal(:rpdealversionId)}")
								.setParameter("rpdealversionId",rpVrsId);
						AppLoger.APPLOGGER.info("storeProcQuery==="+storefpProcQuery);
						List result = storefpProcQuery.list();
						AppLoger.APPLOGGER.info("RESULT");
						AppLoger.APPLOGGER.info(result.size());
						
						
						Query query = session.createQuery("update FpDeal set currentApprovalStatus = :currentApprovalStatus, updatedBy = :updatedBy, updatedDate = :updatedDate, pageTrackerStatus = :pageTrackerStatus where rpDealVersionId = :rpDealVersionId AND isActive = 1");
						query.setParameter("currentApprovalStatus", currentApprovalStatus);
						query.setParameter("updatedBy", fpDetails.get(0).getUpdatedBy());
						query.setParameter("updatedDate", fpDetails.get(0).getUpdatedDate());
						query.setParameter("rpDealVersionId", rpVrsId);
						query.setParameter("pageTrackerStatus", 6);
						updateId = query.executeUpdate();
					}
				}
				
			t.commit();
			session.clear();
			//session.close();	
			return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body("Approval Flow started");
		} catch (Exception e) {
			t.rollback();
			session.clear();
			//session.close();
			return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body("Currently Facing Technical Issue.");
		}
		}
		
