		public ResponseEntity<Object> setSubmitEnabled(String currentUser) {
			// TODO Auto-generated method stub

				Session session = this.sessionFactory.getCurrentSession();
				session.beginTransaction();

				
				Query query = session.createQuery("update atosDataPrePrivacy set checkSubmit= 1, last_updated_by= :lastUpdatedBy, last_updated_dt= :lastUpdatedOn where userId= :currentUser");
				String syntelLanId= getSyntelId(this.auditTrails.getCurrentUser());
				if(syntelLanId.isEmpty() || syntelLanId==null)
				{
					query.setParameter("lastUpdatedBy", this.auditTrails.getCurrentUser());
					query.setParameter("lastUpdatedOn", this.auditTrails.getCurrentTimeStamp());
					query.setParameter("currentUser", this.auditTrails.getCurrentUser());
				}
				else
				{
				query.setParameter("lastUpdatedBy", syntelLanId);
				query.setParameter("lastUpdatedOn", this.auditTrails.getCurrentTimeStamp());
				query.setParameter("currentUser", currentUser);
				}
				
				int result = query.executeUpdate();
				
				session.getTransaction().commit();
				AppLoger.APPLOGGER.info("updated");

				return null;	
		}



