		@Override
		public void updatedverticalMailTrigger() {
			Session session = this.sessionFactory.getCurrentSession();
			String userId = "";
			String newVertical="";
			String oldVertical="";
			String verticalAccessControl="";
			
			try {
				// vertical
				Criteria crit = session.createCriteria(RPFINVerticalRoleEmailScheduler.class,"emailvertiacl");
				List<RPFINVerticalRoleEmailScheduler> accessVerticalList = crit.list();
				AppLoger.APPLOGGER.info("Query Count: " + 4);
				if(accessVerticalList.size()>0) {
					String qryForRateCardName="SELECT c.SR_NO,c.PROCESS_INSTANCE,c.OPRID,c.EMPLID,c.old_Vertical_Id,"
			                  + "c.Old_Sub_Vertical_id,c.Old_Vertical_Name,"
                              +" c.Old_Sub_Vertical_Name,c.New_Vertical_Id,c.New_Sub_Vertical_Id,c.New_Vertical_Name ,c.New_Sub_Vertical_Name ,"
                              + "c.Insertion_On,c.Email_Flag  " 
								+"FROM synprod.RP_FIN_Vertical_Role  c"
								+" WHERE EXISTS(SELECT c2.Lan_Id"
								+" FROM [synprod].[MST_RP_Access_Control] c2"
								+" WHERE c2.Lan_Id = c.OPRID)";
					Query crits = session.createSQLQuery(qryForRateCardName).addEntity(RPFINVerticalRoleEmailScheduler.class);
					
					List<RPFINVerticalRoleEmailScheduler> VerticalsNamelist = crits.list();
					AppLoger.APPLOGGER.info("sIZE: " + VerticalsNamelist.size());
					if(VerticalsNamelist.size()>0){
					for(RPFINVerticalRoleEmailScheduler verticalRolePermiData: VerticalsNamelist){
						if(verticalRolePermiData.getEmailFlag().equals("N")){
						userId=verticalRolePermiData.getOprID();
						newVertical=verticalRolePermiData.getNewVerticalId();
						oldVertical=verticalRolePermiData.getOldVerticalId();
						String userNAme=getRCRequesterName(userId);
						String userEmail=getRCRequesterId(userId);
						int verticalId=Integer.parseInt(oldVertical);
						String deliveryData[]=getUserName(verticalId);
						
						Query qryisActiveAccessControl = session.createQuery("UPDATE AccessControl set isActive=:isActive where lanId = :lanId and verticalId =:verticalId ");
						qryisActiveAccessControl.setParameter("isActive",0);
						qryisActiveAccessControl.setParameter("lanId", verticalRolePermiData.getOprID());
						qryisActiveAccessControl.setParameter("verticalId", verticalId);
						int insertId = qryisActiveAccessControl.executeUpdate();
						AppLoger.APPLOGGER.info("sIZE: " + insertId);
						
						if(insertId>0){
							RightPriceEmailSchedularTemplate  emailTriggerTemplate = new RightPriceEmailSchedularTemplate();
							emailTriggerTemplate.triggerMail(1,userNAme,userEmail,verticalId,deliveryData);
							
							Query qryisActiveUpdate = session.createQuery("UPDATE RPFINVerticalRoleEmailScheduler set emailFlag=:emailFlag where oprID = :oprID");
							qryisActiveUpdate.setParameter("emailFlag","Y");
							qryisActiveUpdate.setParameter("oprID", verticalRolePermiData.getOprID());
							int insertIds = qryisActiveUpdate.executeUpdate();
							AppLoger.APPLOGGER.info("sIZE: " + insertId);
						}
						
						
						
					}
					}
				}
					
					
					
				}
			}catch (Exception e) {
				AppLoger.APPLOGGER.info("Query Count: " + e);
			} 
			finally {
				//session.close();
			}
			
		}

