		@Override
		public List<String> getUserRolesBasedonDasId(String dasID) {
			AppLoger.APPLOGGER.info("Fetching roles for................................ " + dasID);
			int projectID = 0;
			int verticalId = 0;
			String bandGroup = "";
			List<String> userRoles = new ArrayList<>();
			String userType="Others";
			String proxyDisplayFlag = "true";
			try{
				String getUserRoleFromAccessControl = "SELECT DISTINCT TRN_APP_MENU_MAPPING.MENU_ID AS USER_ROLE,MST_ROLE_ID AS ROLEID "
                        + "FROM TRN_ROLE_DETAILS "
                        + "JOIN TRN_APP_MENU_MAPPING ON TRN_ROLE_DETAILS.MENU_ID = TRN_APP_MENU_MAPPING.MENU_ID "
                        + "WHERE TRN_APP_MENU_MAPPING.IS_MENU_ACTIVE = 1 AND TRN_ROLE_DETAILS.ACTIVE_STATUS=1 "
                        + "AND MST_ROLE_ID IN (" 
                        + "SELECT  DISTINCT ROLE_GROUP_CAT_MAPPING.MST_ROLE_ID "
                        + "FROM ROLE_GROUP_CAT_MAPPING "
                        + "JOIN MST_ROLE ON ROLE_GROUP_CAT_MAPPING.MST_ROLE_ID = MST_ROLE.MST_ROLE_ID " 
                        + "WHERE MST_ROLE.APP_ID=3 AND "
                        + "(ROLE_GROUP_CAT_MAPPING.ROLE_ASSIGNMENT_CAT_ID=1 OR "
                        + "(ROLE_GROUP_CAT_MAPPING.ROLE_ASSIGNMENT_CAT_ID=2 AND ROLE_GROUP_CAT_MAPPING.ROLE_ASSIGNMENT_SUB_CAT=? ) OR "
                        + "(ROLE_GROUP_CAT_MAPPING.ROLE_ASSIGNMENT_CAT_ID=3 AND ROLE_GROUP_CAT_MAPPING.ROLE_ASSIGNMENT_SUB_CAT=? ) OR "
                        + "(ROLE_GROUP_CAT_MAPPING.ROLE_ASSIGNMENT_CAT_ID=4 AND ROLE_GROUP_CAT_MAPPING.ROLE_ASSIGNMENT_SUB_CAT=? ) OR "
                        + "(ROLE_GROUP_CAT_MAPPING.ROLE_ASSIGNMENT_CAT_ID=5 AND ROLE_GROUP_CAT_MAPPING.ROLE_ASSIGNMENT_SUB_CAT=?)) "
                        + "AND ROLE_GROUP_CAT_MAPPING.ACTIVE_STATUS = 1 AND MST_ROLE.IS_ROLE_ACTIVE = 1) and TRN_APP_MENU_MAPPING.APP_ID=3";

				AppLoger.APPLOGGER.info("Query : " + getUserRoleFromAccessControl);
				AppLoger.APPLOGGER.info("Query Count: " + 2);
				SqlRowSet roleSet = mysqlTemplate.queryForRowSet(getUserRoleFromAccessControl,
				new Object[] {
						dasID.toUpperCase(), // 2
						projectID, // 3
						verticalId, // 4
						bandGroup// 5
					});
				
				while(roleSet.next())
				{
					
					if (roleSet.getString("ROLEID").contains("5") || roleSet.getString("ROLEID").contains("6")) 
					{
						userType = "GFT";
						CheckUserType.userTypeId = 1;	
						proxyDisplayFlag = "false";
						
					}
					else if (roleSet.getString("ROLEID").contains("7")) 
					{
						userType = "BUH";
						CheckUserType.userTypeId = 2;	
						proxyDisplayFlag = "false";
					} 
					else if (roleSet.getString("ROLEID").contains("8")) 
					{
						userType = "DUH";
						CheckUserType.userTypeId = 3;	
						proxyDisplayFlag = "false";
					} 
					else if (roleSet.getString("ROLEID").contains("10")) 
					{
						userType = "CDO";
						CheckUserType.userTypeId = 2;	
						proxyDisplayFlag = "false";
					} 
					else if (roleSet.getString("ROLEID").contains("9")) 
					{
						userType = "CEO";
						CheckUserType.userTypeId = 2;	
						proxyDisplayFlag = "false";
					} 
					else if (roleSet.getString("ROLEID").contains("11")) 
					{
						userType = "RiskManagers";
						CheckUserType.userTypeId = 4;	
						proxyDisplayFlag = "false";
					} 
					else if (roleSet.getString("ROLEID").contains("13")) 
					{
						userType = "Delivery";
						CheckUserType.userTypeId = 5;	
						proxyDisplayFlag = "false";
					} 
					else if (roleSet.getString("ROLEID").contains("14")) 
					{
						userType = "Audit";
						CheckUserType.userTypeId = 8;	
						proxyDisplayFlag = "false";
					} 
					else if (roleSet.getString("ROLEID").contains("15")) 
					{
						userType = "LEVELl1User";
						CheckUserType.userTypeId = 2;	
						proxyDisplayFlag = "false";
					} 
					else if (roleSet.getString("ROLEID").contains("16")) 
					{
						userType = "LEVELl2User";
						CheckUserType.userTypeId = 2;	
						proxyDisplayFlag = "false";
					} 
					else if (roleSet.getString("ROLEID").contains("23")) 
					{
						userType = "ISSDUSER";
						CheckUserType.userTypeId = 9;	
						proxyDisplayFlag = "false";
					}
						else
						{
							CheckUserType.userTypeId = 7;	
							proxyDisplayFlag = "true";	
						}
						userRoles.add(roleSet.getString("USER_ROLE"));
						AppLoger.APPLOGGER.info("USER_ROLE : " + roleSet.getString("USER_ROLE"));
						AppLoger.APPLOGGER.info("ROLEID : " + roleSet.getString("ROLEID"));
					}
					userRoles.add(proxyDisplayFlag);
			}
			catch(Exception ex)
			{
				AppLoger.APPLOGGER.info("Error occured in getUserRoles: " + ex.getMessage());
				AppLoger.APPLOGGER.info("Error occured in getUserRoles: print stackstrace" + ex.getStackTrace());
				ex.printStackTrace();
			}
//			AppLoger.APPLOGGER.info("NOT ABLE TO GET THE DATA FROM THE SYNTELIGENCE : ");
			userRoles.add(0, userType);
			return userRoles;
		}
		
		
