		@Override
		public ResponseEntity<java.lang.Object> checkCustomerMappingInFin(String crmDealId) {

			try{
			String popupToBeShown ="";
			Session session = this.sessionFactory.getCurrentSession();
			List<SFCustomerMapping> customerIdFromCrmVW = null;
			List<financeCustMapping> customerMappingFromSFVW = null;
			
			Criteria crmCustCheck = session.createCriteria(SFCustomerMapping.class, " customer Data from CRM view")
					.add(Restrictions.eq("strOpportunityID", crmDealId));
	 		
			 customerIdFromCrmVW = crmCustCheck.list();
			 
			 if(customerIdFromCrmVW.size()>0){
				 
				 Criteria sfcustMappingCheck = session.createCriteria(financeCustMapping.class, " customer mapping in Fin")
					 .add(Restrictions.eq("strSySfAcctId", customerIdFromCrmVW.get(0).getStrCustomerGroup()));
				 customerMappingFromSFVW = sfcustMappingCheck.list();
				 if(customerMappingFromSFVW.size()>0){
					 popupToBeShown = "No"; 
				 }
				 else{
					 popupToBeShown = "Yes"; 
				 }
				 
			 }
			 else{
				 popupToBeShown = "No"; 
			 }
				 
			
			if (popupToBeShown.equals("Yes")) {
				//session.close();
				return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(customerIdFromCrmVW);
			} else {
				//session.close();
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("No");
			}
			}catch (Exception e) {
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("No");
			}
		
		}

		
				@Override
		public ResponseEntity<java.lang.Object> CheckUserAccess(Integer accId, String userId) {

			String Authentication="Failed";
			Session session = this.sessionFactory.getCurrentSession();
			
			Query checkAuth = session.createQuery("from AccessControl WHERE lanId=? and isActive=?");
			checkAuth.setParameter(0, userId);
			checkAuth.setParameter(1, 1);
			List<AccessControl> customerAccess = checkAuth.list();
			
			for(int i=0;i<customerAccess.size();i++){
				if(customerAccess.get(i).getCustomerId().equals(accId)){
					Authentication = "Success";
					break;
				}
			}
			
			if (Authentication.equals("Success")) {
				//session.close();
				return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body("Success");
			} else {
				//session.close();
				return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Failed");
			}

		
		}

