				@Override
				public ResponseEntity<Object> updateAssumptionsParamValue(DeductionforUpdate[] deduction) {
					int insertId = 0;
					Session session = this.sessionFactory.getCurrentSession();
					Transaction tc = session.beginTransaction();
					for (DeductionforUpdate updateDeduction : deduction) {
						
						Query query = session.createQuery("UPDATE DeductionforUpdate set parDeduction = :parDeduction,"
								+ "codeName = :codeName "
								+ "where deductionid =:deductionid");
						query.setParameter("parDeduction", updateDeduction.getParDeduction());
						query.setParameter("codeName", updateDeduction.getCodeName());
						query.setParameter("deductionid", updateDeduction.getDeductionid());
						insertId = query.executeUpdate();
					}
					AppLoger.APPLOGGER.info("updated successfully");
					tc.commit();
					//session.close();
					return null;
				}


