				public List getDealDetailsFor_Selection_2(String crmDealId, Session session) {
//					Session session = this.sessionFactory.getCurrentSession();
					Criteria crit;
					List dealCrmData = new ArrayList<>();
					try {
						AppLoger.APPLOGGER.info("Query Count function: " + 75);

						AppLoger.APPLOGGER.info(
								"getDealDetailsForTM_Selection id in dealTypeForTM ------------------------------" + crmDealId);

						crit = session.createCriteria(DealCrmStages.class, "deal").add(Restrictions.eq("isActive", 1))
								.add(Restrictions.eq("crmDealId", crmDealId));

						crit.createCriteria("dealStatus", "dealStatus").add(Restrictions.ilike("codeType", "%Deal_Status%"));
						crit.createCriteria("dealPriority", "dealPriority").add(Restrictions.ilike("codeType", "%deal_priority%"));
						crit.createCriteria("currency", "currency").add(Restrictions.eq("isActive", 1));
						crit.createCriteria("stage", "stage").add(Restrictions.ilike("codeType", "%Deal_Stage%"));
						dealCrmData = crit.list();
						
						AppLoger.APPLOGGER.info(
								"Length of Deal Data " + dealCrmData.size()); /* List<DealCrmStages> dealCrmData = crit.list(); */
						if (!dealCrmData.isEmpty()) {
							AppLoger.APPLOGGER.info("Length of Deal Data " + dealCrmData.size());
							return dealCrmData;
						} else {
							return dealCrmData;
						}
					} catch (Exception e) {
						return dealCrmData;
						//AppLoger.APPLOGGER.info("We're facing technical issues");
					} finally {
						// session.close();
					}
					// return null;
				}


				@Override
				public ResponseEntity<Object> saveDealData(DealCreationDetails_RP_V2 dealDetails) {

					Session session = this.sessionFactory.getCurrentSession();
					String syntelLanId = getSyntelId(this.auditTrails.getCurrentUser());
					if (syntelLanId.isEmpty() || syntelLanId == null) {
						dealDetails.setCreatedBy(this.auditTrails.getCurrentUser());
						dealDetails.setCreatedOn(this.auditTrails.getCurrentTimeStamp());
						dealDetails.setUpdatedBy(this.auditTrails.getCurrentUser());
						dealDetails.setUpdatedOn(this.auditTrails.getCurrentTimeStamp());
					} else {
						dealDetails.setCreatedBy(syntelLanId);
						dealDetails.setCreatedOn(this.auditTrails.getCurrentTimeStamp());
						dealDetails.setUpdatedBy(syntelLanId);
						dealDetails.setUpdatedOn(this.auditTrails.getCurrentTimeStamp());
					}
					String insertId = dealDetails.getDealId();
					try {
						
					session.saveOrUpdate(dealDetails);
						AppLoger.APPLOGGER.info("insert id:-------------------------" + insertId);
					} catch (HibernateException hb) {
						AppLoger.APPLOGGER.info("Exception:--------------" + hb);
					}
					if (insertId != null) {
						AppLoger.APPLOGGER.info("Deal Record Inserted");
						// session.close();
						return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(insertId);
					} else {
						AppLoger.APPLOGGER.info("inside else------------------");
						// session.close();
						return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN)
								.body("Currently We are facing technical issues, please try again later.");
					}
				}
				


