				@Override
				public ResponseEntity<Object> addRProleData(FPDCRCAndProjectDetails role) {
					int insertId = 0;
					Session session = this.sessionFactory.getCurrentSession();
					System.out.println("Inside Respository addRPAccessControlData "+role.getRpRoleAccess().size());
						for (RpRole costDetails : role.getRpRoleAccess()) {
							Query updateHardWareCostDetails = session
									.createQuery("update RpRole set Activestatus = :Activestatus, lastupdatedBy =:lastupdatedBy,lastupdatedOn = :lastupdatedOn  "
											+ "where roleassignmentsubcat= :roleassignmentsubcat");
							updateHardWareCostDetails.setParameter("Activestatus", 0);
							
							updateHardWareCostDetails.setParameter("lastupdatedBy", costDetails.getLastupdatedBy());
							updateHardWareCostDetails.setParameter("lastupdatedOn", costDetails.getLastupdatedOn());
							updateHardWareCostDetails.setParameter("roleassignmentsubcat", costDetails.getRoleassignmentsubcat());
							
							
							insertId = updateHardWareCostDetails.executeUpdate();
						}
						for (RpRole costDetails :  role.getRpRoleAccess()) {
								if(costDetails.getMstroleid()!=0){
								System.out.println("Inside else of update");
								
								insertId = (int) session.save(costDetails);
								AppLoger.APPLOGGER.info("rate card insert id : " + insertId);
							}
						}
					if (insertId > 0) {
						//session.close();
						return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body("Data added successfully");
					} else {
						//session.close();
						return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN)
								.body("Currently We are facing technical issues, please try again later.");
					}
				}


