				@Override
				public ResponseEntity<Object> getXOSkillFromMasterRoleId(int masterRoleId) {
					Session session = this.sessionFactory.getCurrentSession();
					AppLoger.APPLOGGER.info("Query Count function: " + 142);
					try {
						String get_entity = "select distinct Skill_Id,Skill_Name  from [synprod].[MST_RP_XO_Skill_Master] xosm join [synprod].[MST_RP_Master_Roles] spsm "
								+ "on xosm.Skill_Id = spsm.X0_Skill_Id where spsm.MASTER_ROLE_ID=" + masterRoleId
								+ " and xosm.Is_Active=1";
						Query quer = session.createSQLQuery(get_entity).addEntity(XOSkillMaster.class);
						List entityList = quer.list();
						AppLoger.APPLOGGER.info("Getting  CO Skill From Sub Practice Id");
						AppLoger.APPLOGGER.info("Query Count function: " + 142);
						for (Object object : entityList) {
							XOSkillMaster skillMaster = (XOSkillMaster) object;
							AppLoger.APPLOGGER.info("Skill ID  : " + skillMaster.getSkillId());
							AppLoger.APPLOGGER.info("Skill Name  : " + skillMaster.getSkillName());
						}
						if (!entityList.isEmpty()) {
							return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(entityList);
						} else {
							return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently Facing technical issue");
						}
					} catch (Exception e) {
						AppLoger.APPLOGGER.info("Error:" + e.getMessage());
						return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body("Currently Facing technical issue"+e.getMessage());
					} finally {
						//session.close();
					}
				}
