				@Override
				public ResponseEntity<Object> getPLAttachementData(AttachmentMapperPL rpDealVersionId) {
					System.out.println("getPLAttachementData*****************************@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@");

					Session session = this.sessionFactory.getCurrentSession();
					List<AttachmentMapperPL> searchedLists = new ArrayList<AttachmentMapperPL>();
					Map<String, Object> params = new HashMap<String, Object>();
					String getPolicyData = "select Version_Id,RP.Object_Id,RP.File_Name,RP.Object,RP.Created_On,RP.ORIGINAL_FILE_NAME"
							+ " from SYNPROD.RP_OBJECT as RP JOIN synprod.RP_PLAttachments as att on RP.Object_Id = att.Attachment_Id"
							+ " where VERSION_ID=:versionId and RP.Is_Active=1";

					params.put("versionId", rpDealVersionId.getVersionId());
					Query query = (session.createSQLQuery(getPolicyData)).addEntity(AttachmentMapperPL.class);
					AppLoger.APPLOGGER.info(query);

					for (String str : query.getNamedParameters()) {
						query.setParameter(str, params.get(str));
					}

					searchedLists = (List<AttachmentMapperPL>) query.list();
					AppLoger.APPLOGGER.info(searchedLists.size());

					for (Object object : searchedLists) {
						AttachmentMapperPL reportData = (AttachmentMapperPL) object;
						
					}

					if (!searchedLists.isEmpty()) {
						//session.close();
						
						return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body(searchedLists);
					} else {
						//session.close();
						return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN).body(searchedLists);
					}

				}
				
				@Override
				public ResponseEntity<Object> uploadPLFileData(MultipartFile file, String fileName, InputStream uploadedInputStream,
						FileObjectTable fileObj, Integer versionId, PLAttachment fpData) {
					int manualUploadId = 0;	
					try {
						Session session = this.sessionFactory.getCurrentSession();			
						byte[] byteArrayString = file.getBytes();
						ByteArrayInputStream ba = new ByteArrayInputStream(byteArrayString);			
						File files = new File("D:\\FTP\\Rightprice\\Ratecard\\");			
						if (!files.exists()) {
							if (files.mkdirs()) {
								System.out.println(" directories are created!");
							} else {
								System.out.println("Already Present!");
							}
						}
						FileOutputStream outputStream = null;
						String filName = "";
						try {				
							System.out.println("The Original File name is......... "+fileObj.getOriginalFileName());
							File file1 = new File("D:\\FTP\\Rightprice\\Ratecard\\" + fileObj.getOriginalFileName() + ".xlsx");
							int increase = 0;
							filName = fileObj.getOriginalFileName();
							while (file1.exists()) {
								String strMain = fileObj.getOriginalFileName();
								String[] arrSplit = new String[2];
								arrSplit = strMain.split("\\.");
								increase++;
								file1 = new File("D:\\FTP\\Rightprice\\Ratecard\\" + arrSplit[0] + "(" + increase + ")" + ".xlsx");
								filName = arrSplit[0] + "(" + increase + ")";
							}
							outputStream = new FileOutputStream(file1);
						} catch (FileNotFoundException e1) {
							e1.printStackTrace();
						}

						int read = 0;
						byte[] bytes = new byte[1024];
						try {
							while ((read = ba.read(bytes)) != -1) {

								outputStream.write(bytes, 0, read);
							}
							outputStream.close();
						} catch (IOException e1) {
							// TODO Auto-generated catch block
							e1.printStackTrace();
						}
						// File Writing has ended
						fileObj.setFileName(filName);
						int insertId = (int) session.save(fileObj);			

						fpData.setAttachmentId(insertId);
						session.save(fpData);			
						//session.close();
						return ResponseEntity.status(200).contentType(MediaType.TEXT_PLAIN).body("File Inserted SuccesFully");
					} catch (Exception e) {
						return ResponseEntity.status(205).contentType(MediaType.TEXT_PLAIN)
								.body("Currently Facing Technical Issue.");
					}
				}

				
